"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["9465"],{8173(e,n,t){t.r(n),t.d(n,{metadata:()=>i,default:()=>o,frontMatter:()=>a,contentTitle:()=>l,toc:()=>u});var i=JSON.parse('{"docId":"references/paper","permalink":"/fr-FR/docs/references/paper","source":"@site/i18n/fr-FR/lagune-docs-content/references/paper.mdx","title":"Security-Driven Hardening\xa0: une convention pour l\'\xe8re du d\xe9veloppement assist\xe9 par IA","sidebarLabel":"Article m\xe9thodologique","description":"La m\xe9thodologie Security-Driven Hardening (SDH)\xa0: une convention Blue Team adapt\xe9e au contexte pour auditer et durcir les logiciels d\xe9velopp\xe9s avec l\'IA ou en vibe coding.","keywords":["Security-Driven Hardening","SDH","s\xe9curit\xe9 d\xe9fensive","spec-driven development","article Lagune"],"datePublished":"2026-11-04T12:56:29.000Z","dateModified":"2026-11-04T12:56:29.000Z","state":"translated","alternates":[{"locale":"en","permalink":"/docs/references/paper"},{"locale":"pt-BR","permalink":"/pt-BR/docs/references/paper"},{"locale":"es-ES","permalink":"/es-ES/docs/references/paper"},{"locale":"de-DE","permalink":"/de-DE/docs/references/paper"},{"locale":"fr-FR","permalink":"/fr-FR/docs/references/paper"},{"locale":"it-IT","permalink":"/it-IT/docs/references/paper"},{"locale":"tr-TR","permalink":"/tr-TR/docs/references/paper"},{"locale":"uk-UA","permalink":"/uk-UA/docs/references/paper"},{"locale":"ru-RU","permalink":"/ru-RU/docs/references/paper"},{"locale":"zh-CN","permalink":"/zh-CN/docs/references/paper"},{"locale":"ja-JP","permalink":"/ja-JP/docs/references/paper"},{"locale":"ko-KR","permalink":"/ko-KR/docs/references/paper"}]}'),s=t(4848),r=t(8453);let a={id:"paper",title:"Security-Driven Hardening\xa0: une convention pour l'\xe8re du d\xe9veloppement assist\xe9 par IA",sidebar_label:"Article m\xe9thodologique",description:"La m\xe9thodologie Security-Driven Hardening (SDH)\xa0: une convention Blue Team adapt\xe9e au contexte pour auditer et durcir les logiciels d\xe9velopp\xe9s avec l'IA ou en vibe coding.",keywords:["Security-Driven Hardening","SDH","s\xe9curit\xe9 d\xe9fensive","spec-driven development","article Lagune"],source_hash:"030038fc3c922aec5f2f0a11d4dc5a15b92756c7dd17606378f27ad1c018c82b"},l="Security-Driven Hardening (SDH)\xa0: une convention pour l'\xe8re du d\xe9veloppement assist\xe9 par IA",u=[{value:"R\xe9sum\xe9",id:"r\xe9sum\xe9",level:2},{value:"I. Introduction\xa0: la br\xe8che de s\xe9curit\xe9 ouverte par le d\xe9veloppement assist\xe9 par IA",id:"i-introduction-la-br\xe8che-de-s\xe9curit\xe9-ouverte-par-le-d\xe9veloppement-assist\xe9-par-ia",level:2},{value:"II. Contexte et travaux connexes",id:"ii-contexte-et-travaux-connexes",level:2},{value:"III. Le SDH\xa0: d\xe9finition et principes de conception",id:"iii-le-sdh-d\xe9finition-et-principes-de-conception",level:2},{value:"IV. Le flux Blue Team en 5 phases",id:"iv-le-flux-blue-team-en-5-phases",level:2},{value:"charter (politique)",id:"charter-politique",level:3},{value:"detect (d\xe9tection)",id:"detect-d\xe9tection",level:3},{value:"plan (tri)",id:"plan-tri",level:3},{value:"harden (rem\xe9diation)",id:"harden-rem\xe9diation",level:3},{value:"verify (v\xe9rification)",id:"verify-v\xe9rification",level:3},{value:"V. Cl\xf4turabilit\xe9\xa0: un constat a un \xe9tat final",id:"v-cl\xf4turabilit\xe9-un-constat-a-un-\xe9tat-final",level:2},{value:"VI. La dualit\xe9 prolongateur des connaissances du d\xe9veloppeur",id:"vi-la-dualit\xe9-prolongateur-des-connaissances-du-d\xe9veloppeur",level:2},{value:"VII. Sp\xe9cialisations non invocables et prompt \xe0 la demande",id:"vii-sp\xe9cialisations-non-invocables-et-prompt-\xe0-la-demande",level:2},{value:"VIII. Ind\xe9pendance de l&#39;\xe9tat et adaptativit\xe9 non autoritaire",id:"viii-ind\xe9pendance-de-l\xe9tat-et-adaptativit\xe9-non-autoritaire",level:2},{value:"Ind\xe9pendance de l&#39;\xe9tat",id:"ind\xe9pendance-de-l\xe9tat",level:3},{value:"Adaptativit\xe9 non autoritaire",id:"adaptativit\xe9-non-autoritaire",level:3},{value:"IX. Le mode pr\xe9ventif universel\xa0: la m\xeame d\xe9fense pendant la construction du travail",id:"ix-le-mode-pr\xe9ventif-universel-la-m\xeame-d\xe9fense-pendant-la-construction-du-travail",level:2},{value:"X. Security-Driven Hardening face au Spec-Driven Development",id:"x-security-driven-hardening-face-au-spec-driven-development",level:2},{value:"XI. Rigueur d&#39;ing\xe9nierie\xa0: la discipline du suivi",id:"xi-rigueur-ding\xe9nierie-la-discipline-du-suivi",level:2},{value:"XII. Le support\xa0: une architecture ind\xe9pendante de l&#39;agent comme preuve de portabilit\xe9",id:"xii-le-support-une-architecture-ind\xe9pendante-de-lagent-comme-preuve-de-portabilit\xe9",level:2},{value:"XIII. Cas pratique\xa0: le SDH de bout en bout",id:"xiii-cas-pratique-le-sdh-de-bout-en-bout",level:2},{value:"XIV. Quand utiliser le SDH, et ses limites",id:"xiv-quand-utiliser-le-sdh-et-ses-limites",level:2},{value:"XV. Discussion\xa0: positionnement, limites et ce que le SDH ne pr\xe9tend pas",id:"xv-discussion-positionnement-limites-et-ce-que-le-sdh-ne-pr\xe9tend-pas",level:2},{value:"Il prolonge, il ne remplace pas",id:"il-prolonge-il-ne-remplace-pas",level:3},{value:"Exclusivement d\xe9fensif, par construction",id:"exclusivement-d\xe9fensif-par-construction",level:3},{value:"Une v\xe9rification de fond, pas de fa\xe7ade",id:"une-v\xe9rification-de-fond-pas-de-fa\xe7ade",level:3},{value:"Un d\xe9terminisme circonscrit, et nomm\xe9",id:"un-d\xe9terminisme-circonscrit-et-nomm\xe9",level:3},{value:"Co\xfbt et \xe9chelle",id:"co\xfbt-et-\xe9chelle",level:3},{value:"L&#39;utilisateur est l&#39;arbitre final",id:"lutilisateur-est-larbitre-final",level:3},{value:"Objections et r\xe9ponses",id:"objections-et-r\xe9ponses",level:3},{value:"XVI. Les \xe9cueils, et comment le SDH les \xe9vite structurellement",id:"xvi-les-\xe9cueils-et-comment-le-sdh-les-\xe9vite-structurellement",level:2},{value:"XVII. Travaux futurs",id:"xvii-travaux-futurs",level:2},{value:"XVIII. Conclusion",id:"xviii-conclusion",level:2},{value:"R\xe9f\xe9rences",id:"r\xe9f\xe9rences",level:2},{value:"Annexe A\xa0: les principes, mot pour mot",id:"annexe-a-les-principes-mot-pour-mot",level:2}];function c(e){let n={a:"a",blockquote:"blockquote",code:"code",em:"em",h2:"h2",h3:"h3",hr:"hr",li:"li",ol:"ol",p:"p",pre:"pre",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,r.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:(0,s.jsx)(n.strong,{children:"Weslley Ara\xfajo"})}),"\n",(0,s.jsx)(n.li,{children:(0,s.jsx)(n.strong,{children:"Article m\xe9thodologique, 2026."})}),"\n"]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"r\xe9sum\xe9",children:"R\xe9sum\xe9"}),"\n",(0,s.jsx)(n.p,{children:"Le Security-Driven Hardening (SDH) est une m\xe9thodologie de s\xe9curit\xe9 structur\xe9e, pilot\xe9e par IA et exclusivement d\xe9fensive, pens\xe9e pour une \xe9poque o\xf9 les logiciels sont de plus en plus \xe9crits par des agents IA et par des personnes qui ne sont pas sp\xe9cialistes de la s\xe9curit\xe9. Au lieu de d\xe9rouler une checklist g\xe9n\xe9rique, le SDH d\xe9tecte d'abord ce que fait r\xe9ellement un syst\xe8me (connexion, envoi de fichiers, paiements, exposition de donn\xe9es, etc.), puis pilote le travail de s\xe9curit\xe9 propre \xe0 ce contexte. Il est gouvern\xe9 par des principes s\xfbrs par d\xe9faut, enti\xe8rement tourn\xe9 vers la d\xe9fense, et formul\xe9 en langage courant pour que tout utilisateur puisse agir en cons\xe9quence."}),"\n",(0,s.jsxs)(n.p,{children:["Ce document soutient que le SDH est une convention qui manquait, et non un outil isol\xe9. Les connaissances de s\xe9curit\xe9 r\xe9sident dans la m\xe9thodologie et ses sp\xe9cialisations \xe0 la demande, une base sur laquelle chaque utilisateur peut construire, ce qui lui permet de servir un d\xe9butant et un expert par le m\xeame flux. Deux propri\xe9t\xe9s le distinguent des approches spec-first ant\xe9rieures ",(0,s.jsx)(n.code,{children:"[1]"}),". Le SDH est ",(0,s.jsx)(n.strong,{children:"ind\xe9pendant de l'\xe9tat"}),"\xa0: il s'adapte \xe0 un r\xe9pertoire vide, \xe0 un projet en cours, \xe0 une seule pull request ou \xe0 une vaste base de code h\xe9rit\xe9e, dans n'importe quelle stack. Et le SDH est ",(0,s.jsx)(n.strong,{children:"cl\xf4turable"}),"\xa0: un risque dont la cl\xf4ture est v\xe9rifi\xe9e est retir\xe9 de tout le flux, si bien que ce constat atteint un \xe9tat stable et n'est rouvert que lorsque le code change. Le SDH ne remplace ni les professionnels de la s\xe9curit\xe9 ni les outils Blue Team sp\xe9cialis\xe9s. Il prolonge les connaissances propres du d\xe9veloppeur, et plus un d\xe9veloppeur comprend la s\xe9curit\xe9, plus il peut le piloter."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Lagune"})," en est l'impl\xe9mentation de r\xe9f\xe9rence, et il prouve que la m\xe9thodologie est r\xe9alisable et portable. Le SDH est propos\xe9 comme une convention que d'autres peuvent adopter."]}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"Mots-cl\xe9s"})}),"\n",(0,s.jsx)(n.p,{children:"D\xe9veloppement assist\xe9 par IA, s\xe9curit\xe9 logicielle, s\xe9curit\xe9 d\xe9fensive, spec-driven development, durcissement de la s\xe9curit\xe9, workflows pilot\xe9s par agent, cl\xf4turabilit\xe9, s\xe9curit\xe9 adapt\xe9e au contexte, connaissances \xe0 la demande, outillage ind\xe9pendant de l'agent."}),"\n"]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"i-introduction-la-br\xe8che-de-s\xe9curit\xe9-ouverte-par-le-d\xe9veloppement-assist\xe9-par-ia",children:"I. Introduction\xa0: la br\xe8che de s\xe9curit\xe9 ouverte par le d\xe9veloppement assist\xe9 par IA"}),"\n",(0,s.jsxs)(n.p,{children:["Les logiciels sont de plus en plus livr\xe9s par des personnes, et par des agents IA, incapables de reconna\xeetre de fa\xe7on fiable un motif non s\xfbr\xa0: un secret divulgu\xe9, une v\xe9rification d'autorisation manquante, une requ\xeate injectable. Ce ne sont pas des risques exotiques. Ils figurent parmi les classes de risques qui dominent les incidents r\xe9els, document\xe9es depuis des ann\xe9es dans des r\xe9f\xe9rences publiques ",(0,s.jsx)(n.code,{children:"[6]"}),", ",(0,s.jsx)(n.code,{children:"[7]"}),", et des \xe9tudes r\xe9centes indiquent qu'une part significative du code g\xe9n\xe9r\xe9 par IA est livr\xe9e avec exactement ce type de d\xe9fauts ",(0,s.jsx)(n.code,{children:"[8]"}),". Les assistants de programmation IA ont aggrav\xe9 la situation en permettant \xe0 des non-d\xe9veloppeurs de livrer de vrais logiciels, mais la br\xe8che d\xe9passe un seul public. La plupart des projets ne b\xe9n\xe9ficient jamais d'un passage de s\xe9curit\xe9 propre \xe0 ce qu'ils font r\xe9ellement. L'\xe9cosyst\xe8me se fragilise \xe0 chaque d\xe9cision pr\xe9matur\xe9e du type \"\xe7a marche, on livre\"."]}),"\n",(0,s.jsx)(n.p,{children:"Les conseils de s\xe9curit\xe9 g\xe9n\xe9riques ne comblent pas cette br\xe8che. Une checklist statique n'est pas propre \xe0 ce que fait un syst\xe8me\xa0: elle submerge un petit projet d'\xe9l\xe9ments sans rapport et passe malgr\xe9 tout \xe0 c\xf4t\xe9 du risque qui compte pour ce projet pr\xe9cis. Le probl\xe8me n'est pas un manque de connaissances en s\xe9curit\xe9 dans le monde. Le probl\xe8me est de faire correspondre les bonnes connaissances au syst\xe8me qui se trouve r\xe9ellement devant l'utilisateur, et de le faire pour quelqu'un qui ne sait peut-\xeatre pas quoi demander."}),"\n",(0,s.jsxs)(n.p,{children:["Le SDH y r\xe9pond par une seule inversion\xa0: ",(0,s.jsx)(n.strong,{children:"les connaissances de s\xe9curit\xe9 r\xe9sident dans la sp\xe9cification et ses sp\xe9cialisations \xe0 la demande, une base sur laquelle chaque utilisateur peut construire"}),". La m\xe9thodologie d\xe9tecte le contexte, trie les risques que porte ce contexte et guide les correctifs, si bien qu'un d\xe9veloppeur et un non-d\xe9veloppeur sont servis par le m\xeame flux. Les constats et les recommandations restent en langage courant, pour \xeatre exploitables quel que soit le niveau technique du lecteur. L'expert n'en est pas brid\xe9, mais amplifi\xe9, une dualit\xe9 que nous d\xe9veloppons en ",(0,s.jsx)(n.code,{children:"\xa7VI"}),"."]}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"Id\xe9e cl\xe9"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"L'inversion centrale :"})," les connaissances de s\xe9curit\xe9 r\xe9sident dans la sp\xe9cification et ses sp\xe9cialisations \xe0 la demande, une base sur laquelle chaque utilisateur peut construire. La m\xe9thodologie apprend ce que fait le syst\xe8me et y fait correspondre le travail de s\xe9curit\xe9, et elle prolonge tout ce que l'utilisateur sait d\xe9j\xe0."]}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Prenons un d\xe9veloppeur qui dit \xe0 un assistant IA\xa0: \"mon application permet aux utilisateurs d'envoyer une photo de profil.\" Sans passage de s\xe9curit\xe9, l'assistant produit du code fonctionnel qui fait discr\xe8tement confiance \xe0 tout ce qu'envoie le client\xa0: le type de fichier d\xe9clar\xe9, le nom du fichier, la taille. L'envoi est livr\xe9, et un fichier d\xe9guis\xe9 en image peut contenir du code, un nom forg\xe9 peut sortir du chemin de stockage, un fichier surdimensionn\xe9 peut \xe9puiser le serveur. Rien de tout cela n'est visible dans une d\xe9mo, donc c'est livr\xe9."}),"\n",(0,s.jsx)(n.p,{children:"Le m\xeame code pass\xe9 par le SDH se comporte autrement. Il d\xe9tecte que le syst\xe8me accepte des fichiers venant de l'ext\xe9rieur (d\xe9tection), le traduit en risques que porte un envoi de fichiers (tri), propose de v\xe9rifier le type r\xe9el et la taille du fichier, de le renommer \xe0 l'enregistrement et de le stocker l\xe0 o\xf9 du code ne peut pas s'ex\xe9cuter (rem\xe9diation), puis lit le r\xe9sultat et confirme que chaque mesure de protection est r\xe9ellement efficace (v\xe9rification). Le d\xe9veloppeur n'a jamais eu besoin de conna\xeetre l'expression \"envoi de fichiers sans restriction\". La m\xe9thodologie l'a fournie \xe0 sa place."}),"\n",(0,s.jsx)(n.p,{children:"Ce document apporte les contributions suivantes\xa0:"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:["Une d\xe9finition pr\xe9cise du SDH en tant que m\xe9thodologie, ind\xe9pendante de toute impl\xe9mentation, avec ses principes de conception (",(0,s.jsx)(n.code,{children:"\xa7III"}),")."]}),"\n",(0,s.jsxs)(n.li,{children:["Un cycle de vie d\xe9fensif en cinq phases dans lequel la s\xe9paration des responsabilit\xe9s est elle-m\xeame la contribution\xa0: la d\xe9tection n'invente jamais, la planification ne lit jamais le code, une seule phase modifie le code, et la v\xe9rification n'assouplit jamais son jugement (",(0,s.jsx)(n.code,{children:"\xa7IV"}),")."]}),"\n",(0,s.jsxs)(n.li,{children:["La ",(0,s.jsx)(n.strong,{children:"cl\xf4turabilit\xe9"})," comme position m\xe9thodologique\xa0: un constat individuel a un \xe9tat final, pas une boucle sans fin (",(0,s.jsx)(n.code,{children:"\xa7V"}),")."]}),"\n",(0,s.jsxs)(n.li,{children:["La dualit\xe9 ",(0,s.jsx)(n.strong,{children:"prolongateur des connaissances du d\xe9veloppeur"}),"\xa0: un m\xeame flux qui prot\xe8ge le d\xe9butant et amplifie l'expert (",(0,s.jsx)(n.code,{children:"\xa7VI"}),")."]}),"\n",(0,s.jsxs)(n.li,{children:["Les ",(0,s.jsx)(n.strong,{children:"sp\xe9cialisations non invocables et le prompt \xe0 la demande"}),"\xa0: des connaissances de s\xe9curit\xe9 cibl\xe9es que l'agent charge quand le contexte du projet l'exige, jamais par d\xe9faut (",(0,s.jsx)(n.code,{children:"\xa7VII"}),")."]}),"\n",(0,s.jsxs)(n.li,{children:["L'",(0,s.jsx)(n.strong,{children:"ind\xe9pendance de l'\xe9tat"})," et l'",(0,s.jsx)(n.strong,{children:"adaptativit\xe9 non autoritaire"}),"\xa0: le SDH convient \xe0 n'importe quel \xe9tat de d\xe9veloppement et s'adapte au sc\xe9nario au lieu d'imposer un p\xe9rim\xe8tre fixe (",(0,s.jsx)(n.code,{children:"\xa7VIII"}),")."]}),"\n",(0,s.jsxs)(n.li,{children:["Un ",(0,s.jsx)(n.strong,{children:"mode pr\xe9ventif"}),"\xa0: la m\xeame d\xe9fense ex\xe9cut\xe9e pendant la construction du travail ordinaire, pour que le code arrive s\xfbr par d\xe9faut et que les phases aient moins \xe0 corriger (",(0,s.jsx)(n.code,{children:"\xa7IX"}),")."]}),"\n",(0,s.jsxs)(n.li,{children:["Une comparaison d\xe9di\xe9e avec le Spec-Driven Development, la lign\xe9e dont le SDH est issu avant de s'en \xe9carter (",(0,s.jsx)(n.code,{children:"\xa7X"}),")."]}),"\n",(0,s.jsxs)(n.li,{children:["Les disciplines d'ing\xe9nierie qui permettent \xe0 la m\xe9thodologie de survivre aux refactorisations et de rester ind\xe9pendante de tout agent\xa0: le suivi par identit\xe9 de nom (",(0,s.jsx)(n.code,{children:"\xa7XI"}),") et un support ind\xe9pendant de l'agent (",(0,s.jsx)(n.code,{children:"\xa7XII"}),")."]}),"\n"]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"ii-contexte-et-travaux-connexes",children:"II. Contexte et travaux connexes"}),"\n",(0,s.jsxs)(n.p,{children:["Le SDH s'appuie sur des travaux ant\xe9rieurs. Il h\xe9rite d'une structure \xe9prouv\xe9e du d\xe9veloppement spec-first pilot\xe9 par agent ",(0,s.jsx)(n.code,{children:"[1]"}),", ",(0,s.jsx)(n.code,{children:"[2]"}),", ",(0,s.jsx)(n.code,{children:"[3]"})," : des mod\xe8les, des commandes slash qu'un agent consomme, un document de gouvernance et un agent qui ex\xe9cute les phases. Il r\xe9impl\xe9mente cette structure dans un but d\xe9fensif. La filiation est d\xe9lib\xe9r\xe9e, et l'un des principes de travail du SDH la nomme directement\xa0: construire le workflow \xe0 partir d'une structure \xe9prouv\xe9e, puis l'orienter vers la s\xe9curit\xe9."]}),"\n",(0,s.jsx)(n.p,{children:"Le SDH n'est pas une checklist statique de recommandations g\xe9n\xe9riques. Une checklist sait beaucoup de choses sur la s\xe9curit\xe9 en g\xe9n\xe9ral et rien sur le projet qui se trouve devant elle. Le SDH inverse cette priorit\xe9. Il consacre son premier effort \xe0 la d\xe9tection, \xe0 apprendre ce que fait le syst\xe8me, et seulement ensuite il va chercher les connaissances que la d\xe9tection rend pertinentes."}),"\n",(0,s.jsxs)(n.p,{children:["Le SDH ne remplace pas non plus les sp\xe9cialistes de la s\xe9curit\xe9 ni les outils Blue Team sp\xe9cialis\xe9s. Il prolonge les connaissances du d\xe9veloppeur (",(0,s.jsx)(n.code,{children:"\xa7VI"}),"). Une \xe9quipe dot\xe9e d'une fonction de s\xe9curit\xe9 d\xe9di\xe9e doit la conserver. Le SDH donne \xe0 cette \xe9quipe un support structur\xe9, et \xe0 une \xe9quipe qui n'en a pas, une base d\xe9fendable."]}),"\n",(0,s.jsxs)(n.p,{children:["Le SDH se place aussi \xe0 c\xf4t\xe9 des scanners de s\xe9curit\xe9 d\xe9terministes (analyse statique, linters) ",(0,s.jsx)(n.code,{children:"[4]"}),", ",(0,s.jsx)(n.code,{children:"[5]"}),". Ces outils sont pr\xe9cieux justement parce qu'ils sont d\xe9terministes et reproductibles. Le SDH repose surtout sur le raisonnement de l'agent, ce qui \xe9change un d\xe9terminisme strict contre l'adaptation au contexte. La m\xe9thodologie ne pr\xe9tend pas le contraire. L\xe0 o\xf9 le d\xe9terminisme compte, elle int\xe8gre un moteur d\xe9terministe au sein du raisonnement (",(0,s.jsx)(n.code,{children:"\xa7VII"}),")\xa0: l'agent d\xe9cide si une entr\xe9e m\xe9rite d'\xeatre v\xe9rifi\xe9e, et un programme d\xe9terministe d\xe9cide si cette entr\xe9e est dangereuse."]}),"\n",(0,s.jsxs)(n.p,{children:["L'ant\xe9riorit\xe9 la plus directe est le Spec-Driven Development (SDD), la famille de m\xe9thodologies spec-first qui fait avancer une construction \xe0 partir d'une sp\xe9cification ex\xe9cutable. Nous traitons le SDD comme une classe. Sa formulation la plus claire en tant que m\xe9thodologie de praticien est le rapport de Piskala ",(0,s.jsx)(n.code,{children:"[1]"}),", et sa bo\xeete \xe0 outils pilot\xe9e par agent la plus visible est Spec Kit de GitHub ",(0,s.jsx)(n.code,{children:"[2]"}),", avec OpenSpec ",(0,s.jsx)(n.code,{children:"[3]"})," comme second outil de la m\xeame famille. Ce sont les r\xe9f\xe9rences canoniques de la comparaison en ",(0,s.jsx)(n.code,{children:"\xa7X"}),"."]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"iii-le-sdh-d\xe9finition-et-principes-de-conception",children:"III. Le SDH\xa0: d\xe9finition et principes de conception"}),"\n",(0,s.jsxs)(n.p,{children:["Le ",(0,s.jsx)(n.strong,{children:"Security-Driven Hardening"})," est une m\xe9thodologie de s\xe9curit\xe9 structur\xe9e et pilot\xe9e par IA qui rend une base de code plus s\xfbre en conduisant le travail \xe0 partir d'une sp\xe9cification qu'ex\xe9cute l'agent, plut\xf4t qu'\xe0 partir de correctifs ponctuels. Son nom s'inspire des ",(0,s.jsx)(n.strong,{children:"Blue Teams"}),", les d\xe9fenseurs en s\xe9curit\xe9. Le SDH porte sur la d\xe9fense, le durcissement et la v\xe9rification, jamais sur l'attaque."]}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"D\xe9finition"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Security-Driven Hardening (SDH) :"})," une m\xe9thodologie de s\xe9curit\xe9 structur\xe9e, pilot\xe9e par IA et exclusivement d\xe9fensive, qui d\xe9tecte d'abord ce que fait r\xe9ellement un syst\xe8me, puis pilote le travail de s\xe9curit\xe9 propre \xe0 ce contexte, gouvern\xe9e par des principes s\xfbrs par d\xe9faut et formul\xe9e en langage courant."]}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Le SDH se d\xe9finit par un ensemble de principes contraignants. Chacun est une r\xe8gle, et chacun conf\xe8re une garantie pr\xe9cise \xe0 l'utilisateur."}),"\n",(0,s.jsxs)(n.table,{children:[(0,s.jsx)(n.thead,{children:(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.th,{children:"Principe"}),(0,s.jsx)(n.th,{children:"La r\xe8gle"}),(0,s.jsx)(n.th,{children:"Ce qu'il garantit \xe0 l'utilisateur"})]})}),(0,s.jsxs)(n.tbody,{children:[(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"S\xfbr par d\xe9faut, en langage courant, pour tous \xe0 \xe9galit\xe9"}),(0,s.jsx)(n.td,{children:"Chaque valeur par d\xe9faut, chaque message et chaque correctif est s\xfbr d'embl\xe9e et compr\xe9hensible par tout lecteur, d\xe9veloppeur ou non. Aucun profil d'utilisateur n'est privil\xe9gi\xe9."}),(0,s.jsx)(n.td,{children:"Un d\xe9butant re\xe7oit une base s\xfbre sans la demander, et lit le r\xe9sultat dans ses propres termes."})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Le contexte plut\xf4t que le g\xe9n\xe9rique"}),(0,s.jsx)(n.td,{children:"Chaque phase part du contexte d\xe9tect\xe9 par detect et agit sur ce que fait r\xe9ellement le syst\xe8me."}),(0,s.jsx)(n.td,{children:"Les recommandations correspondent au projet, pas \xe0 une checklist. Les connaissances de s\xe9curit\xe9 r\xe9sident dans la sp\xe9cification et ses sp\xe9cialisations \xe0 la demande, et prolongent tout ce qu'apporte l'utilisateur."})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"La souplesse plut\xf4t que la rigidit\xe9"}),(0,s.jsx)(n.td,{children:"Les principes, exigences et recommandations sont des points de d\xe9part. L'utilisateur peut reformuler, supprimer, ajouter ou r\xe9duire la port\xe9e de n'importe quoi."}),(0,s.jsx)(n.td,{children:"La m\xe9thodologie s'adapte au projet et \xe0 l'utilisateur, et ne se montre jamais plus stricte que ce que l'utilisateur souhaite. La souplesse n'affaiblit jamais la base s\xfbre par d\xe9faut."})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Mettre en coh\xe9rence, jamais seulement ajouter"}),(0,s.jsx)(n.td,{children:"Les artefacts sont des documents vivants, pas des journaux. Chaque ex\xe9cution rev\xe9rifie chaque entr\xe9e\xa0: garder ce qui tient, r\xe9\xe9crire ce qui a chang\xe9, supprimer ce qui ne s'applique plus."}),(0,s.jsx)(n.td,{children:"Le registre refl\xe8te toujours le pr\xe9sent, donc il ne se d\xe9grade jamais en backlog p\xe9rim\xe9."})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Exclusivement d\xe9fensif"}),(0,s.jsx)(n.td,{children:"Le SDH audite, durcit et v\xe9rifie. Il ne produit jamais d'outils offensifs, d'exploits \xe0 usage malveillant ni de contournement de la d\xe9tection \xe0 des fins nuisibles."}),(0,s.jsx)(n.td,{children:"La m\xe9thodologie ne peut pas \xeatre transform\xe9e en arme. Le contenu \xe0 double usage n'appara\xeet que dans un cadre clairement d\xe9fensif."})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Spec-first, pilot\xe9 par agent, orient\xe9 vers la s\xe9curit\xe9"}),(0,s.jsx)(n.td,{children:"Le workflow est construit \xe0 partir de mod\xe8les, de commandes, de principes de s\xe9curit\xe9 qui gouvernent et d'un agent qui ex\xe9cute les phases."}),(0,s.jsx)(n.td,{children:"Une structure de d\xe9veloppement \xe9prouv\xe9e, r\xe9affect\xe9e pour que l'agent accomplisse le travail de s\xe9curit\xe9 de fond."})]})]})]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Tableau 1."})," Les principes de conception du SDH et la garantie que chacun conf\xe8re \xe0 l'utilisateur."]}),"\n",(0,s.jsxs)(n.p,{children:["Ces principes ne sont pas d\xe9coratifs. Ce sont les contraintes que chaque phase ci-dessous doit respecter, et la discussion en ",(0,s.jsx)(n.code,{children:"\xa7XV"})," y revient pour marquer les limites de la m\xe9thodologie."]}),"\n",(0,s.jsx)(n.p,{children:"La suite du document d\xe9veloppe neuf piliers nomm\xe9s. Ce sont les \xe9l\xe9ments qu'un lecteur doit pouvoir garder en t\xeate, et ceux qu'une autre \xe9quipe r\xe9impl\xe9menterait pour affirmer qu'elle pratique le SDH."}),"\n",(0,s.jsxs)(n.table,{children:[(0,s.jsx)(n.thead,{children:(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.th,{children:"Pilier"}),(0,s.jsx)(n.th,{children:"Ce qu'il apporte"}),(0,s.jsx)(n.th,{children:"Section"})]})}),(0,s.jsxs)(n.tbody,{children:[(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"L'inversion adapt\xe9e au contexte"}),(0,s.jsx)(n.td,{children:"Les connaissances de s\xe9curit\xe9 r\xe9sident dans la sp\xe9cification et ses sp\xe9cialisations \xe0 la demande, donc un d\xe9butant et un expert partagent un m\xeame flux."}),(0,s.jsxs)(n.td,{children:[(0,s.jsx)(n.code,{children:"\xa7I"}),", ",(0,s.jsx)(n.code,{children:"\xa7VI"})]})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Le cycle de vie d\xe9fensif en cinq phases"}),(0,s.jsx)(n.td,{children:"La s\xe9paration des responsabilit\xe9s\xa0: politique, d\xe9tection, tri, rem\xe9diation, v\xe9rification, chacune avec une seule mission."}),(0,s.jsx)(n.td,{children:(0,s.jsx)(n.code,{children:"\xa7IV"})})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"La cl\xf4turabilit\xe9"}),(0,s.jsx)(n.td,{children:"Un constat a un \xe9tat final, pas une boucle sans fin. Le travail cl\xf4tur\xe9 est retir\xe9."}),(0,s.jsx)(n.td,{children:(0,s.jsx)(n.code,{children:"\xa7V"})})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"La dualit\xe9 prolongateur des connaissances du d\xe9veloppeur"}),(0,s.jsx)(n.td,{children:"Un m\xeame flux qui prot\xe8ge le d\xe9butant et amplifie l'expert, sans jamais remplacer ni l'un ni l'autre."}),(0,s.jsx)(n.td,{children:(0,s.jsx)(n.code,{children:"\xa7VI"})})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Le prompt \xe0 la demande, des connaissances non invocables"}),(0,s.jsx)(n.td,{children:"Les connaissances de s\xe9curit\xe9 pertinentes sont charg\xe9es pour ce qu'est le projet, jamais par d\xe9faut."}),(0,s.jsx)(n.td,{children:(0,s.jsx)(n.code,{children:"\xa7VII"})})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"L'ind\xe9pendance de l'\xe9tat et l'adaptativit\xe9 non autoritaire"}),(0,s.jsx)(n.td,{children:"Convient \xe0 n'importe quel \xe9tat de d\xe9veloppement dans n'importe quelle stack, et s'adapte au sc\xe9nario au lieu d'imposer un p\xe9rim\xe8tre."}),(0,s.jsx)(n.td,{children:(0,s.jsx)(n.code,{children:"\xa7VIII"})})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Le mode pr\xe9ventif"}),(0,s.jsx)(n.td,{children:"La m\xeame d\xe9fense s'ex\xe9cute pendant la construction du nouveau travail, pour que le code arrive s\xfbr par d\xe9faut."}),(0,s.jsx)(n.td,{children:(0,s.jsx)(n.code,{children:"\xa7IX"})})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Le suivi par identit\xe9 de nom"}),(0,s.jsx)(n.td,{children:"Un constat reste un seul \xe9l\xe9ment d'une phase \xe0 l'autre, et un renommage ne casse le lien qu'\xe0 un seul endroit."}),(0,s.jsx)(n.td,{children:(0,s.jsx)(n.code,{children:"\xa7XI"})})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Le support ind\xe9pendant de l'agent"}),(0,s.jsx)(n.td,{children:"La valeur de s\xe9curit\xe9 est \xe9crite une seule fois et ne d\xe9pend d'aucun agent ni d'aucune stack."}),(0,s.jsx)(n.td,{children:(0,s.jsx)(n.code,{children:"\xa7XII"})})]})]})]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Tableau 2."})," Les neuf piliers nomm\xe9s du SDH et l'endroit o\xf9 chacun est d\xe9velopp\xe9."]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"iv-le-flux-blue-team-en-5-phases",children:"IV. Le flux Blue Team en 5 phases"}),"\n",(0,s.jsx)(n.p,{children:"Le SDH structure le travail en un cycle de vie d\xe9fensif en cinq phases (figure 1). Chaque phase est orient\xe9e vers la d\xe9fense, chacune s'appuie sur la pr\xe9c\xe9dente, et les phases suivent l'activit\xe9 r\xe9elle d'une Blue Team\xa0: \xe9tablir une politique, d\xe9tecter, trier, rem\xe9dier, v\xe9rifier."}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-mermaid",children:'flowchart TB\n    charter["1 \xb7 charter (politique)<br/>lit : le projet, et la description de l\'utilisateur si elle est fournie<br/>\xe9crit : les principes de s\xe9curit\xe9<br/>chaque principe porte le risque qu\'il pr\xe9vient, en langage courant"]\n    detect["2 \xb7 detect (d\xe9tection)<br/>lit : le code de l\'utilisateur<br/>\xe9crit : la cartographie<br/>d\xe9tection, pas invention : ne consigner que ce que le code \xe9taye"]\n    plan["3 \xb7 plan (tri)<br/>lit : la cartographie, jamais le code<br/>\xe9crit : le plan de d\xe9fense<br/>chaque correctif pointe vers quelque chose que detect a r\xe9ellement cartographi\xe9"]\n    harden["4 \xb7 harden (rem\xe9diation)<br/>lit : le plan de d\xe9fense, et le code qu\'il touche<br/>\xe9crit : le code, et le registre de durcissement<br/>la seule phase qui modifie le code, un correctif \xe0 la fois, la plus petite modification efficace"]\n    verify["5 \xb7 verify (v\xe9rification)<br/>lit : le code, et le registre de durcissement<br/>\xe9crit : chaque verdict ouvert dans le registre de durcissement<br/>la confrontation du code avec le registre, de fa\xe7on statique, jamais adoucie"]\n    charter --\x3e detect --\x3e plan --\x3e harden --\x3e verify\n    verify -.->|"rejet\xe9 : travail rouvert pour harden,<br/>r\xe9appliqu\xe9 selon la raison consign\xe9e"| harden\n    verify -.->|"cl\xf4ture : retire ce qu\'il a prouv\xe9 cl\xf4tur\xe9<br/>de toute la cha\xeene,<br/>une ligne dans l\'historique"| detect\n'})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Figure 1."})," Le flux en cinq phases\xa0: ce que lit chaque phase, ce qu'elle \xe9crit et son invariant structurant. Verify d\xe9clenche les deux retours\xa0: une mesure rejet\xe9e rouvre harden, et un constat dont la cl\xf4ture est prouv\xe9e est retir\xe9 de la cha\xeene, avec une ligne dans l'historique."]}),"\n",(0,s.jsx)(n.p,{children:"La s\xe9paration des responsabilit\xe9s est la contribution. Comme chaque phase a une seule mission, un mode de d\xe9faillance reste confin\xe9 \xe0 un seul endroit, et le lecteur peut se fier \xe0 ce qu'affirme chaque artefact."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"Id\xe9e cl\xe9"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Appliqu\xe9 ne veut pas dire v\xe9rifi\xe9 :"})," harden consigne qu'un correctif a \xe9t\xe9 appliqu\xe9. Verify le v\xe9rifie en confrontant le code \xe0 ce registre, et le verdict n'est jamais adouci pour correspondre au registre. Une mesure de protection peut \xeatre pr\xe9sente dans le code et laisser malgr\xe9 tout le risque atteignable, et le verdict honn\xeate est alors \"risque non cl\xf4tur\xe9\"."]}),"\n"]}),"\n",(0,s.jsx)(n.h3,{id:"charter-politique",children:"charter (politique)"}),"\n",(0,s.jsxs)(n.p,{children:["La phase charter \xe9tablit les principes de s\xe9curit\xe9 du projet, les r\xe8gles que chaque phase suivante doit respecter. C'est la couche de gouvernance, une sorte de v\xe9rification \xe0 la compilation de la posture de s\xe9curit\xe9 du projet. Chaque principe a un nom clair, une r\xe8gle non n\xe9gociable qui peut \xeatre v\xe9rifi\xe9e dans le code, et une ligne ",(0,s.jsx)(n.code,{children:"Why:"})," qui \xe9nonce le risque qu'il pr\xe9vient, pas seulement le correctif. La phase charter lit toujours le projet lui-m\xeame (ses manifestes, sa structure et ses d\xe9pendances), et la description de l'utilisateur, quand elle est fournie, donne une direction que la lecture \xe9largit ensuite au-del\xe0 de ce que l'utilisateur a nomm\xe9. Sans description, le projet est la seule source. Les deux se compl\xe8tent au lieu de se concurrencer, et la phase charter consigne la politique que le projet doit respecter, pas l'\xe9tat de son code. Un non-d\xe9veloppeur doit pouvoir la lire et comprendre \xe0 la fois la r\xe8gle et le risque."]}),"\n",(0,s.jsx)(n.h3,{id:"detect-d\xe9tection",children:"detect (d\xe9tection)"}),"\n",(0,s.jsxs)(n.p,{children:["Detect lit le code et cartographie ce que fait r\xe9ellement le syst\xe8me qui p\xe8se sur la s\xe9curit\xe9. Sa consigne directrice est \"la d\xe9tection, pas l'invention\"\xa0: ne consigner que ce que le code \xe9taye, avec les \xe9l\xe9ments de preuve dont les phases suivantes ont besoin. Detect est neutre. Il ne force pas ses constats \xe0 cadrer avec les principes de s\xe9curit\xe9, car confronter les risques aux r\xe8gles de la charter est le travail de la phase plan. Chaque constat comporte trois parties\xa0: ce qu'il est (description en langage courant), pourquoi il compte (le risque, pas seulement le fait) et l'\xe9l\xe9ment de preuve (la fonction ou la route o\xf9 il se trouve). L'\xe9l\xe9ment de preuve ne contient aucun chemin de fichier. Le chemin ne se trouve que dans la carte de suivi (",(0,s.jsx)(n.code,{children:"\xa7XI"}),"), donc le texte ne contient jamais un chemin susceptible de devenir obsol\xe8te."]}),"\n",(0,s.jsx)(n.h3,{id:"plan-tri",children:"plan (tri)"}),"\n",(0,s.jsx)(n.p,{children:"Plan transforme chaque constat en correctif, nomm\xe9 par sa classe de risque (en citant les r\xe9f\xe9rences \xe9tablies, CWE et OWASP, quand elles le fondent) et rattach\xe9 au principe de s\xe9curit\xe9 que le correctif fait respecter. La priorit\xe9 (Critical, High, Medium, Low) n'est pas un choix libre\xa0: plan \xe9value chaque constat avec la m\xe9thode CVSS v4.0 Base et Environmental, donc la tranche est le score exprim\xe9 en mots, justifi\xe9e par une ligne en langage courant sur l'exposition et les enjeux, et deux ex\xe9cutions aboutissent au m\xeame ordre. Le vecteur est l'ancrage pr\xe9cis pour un expert, la tranche et sa justification sont la m\xeame \xe9valuation que n'importe qui peut suivre. Plan travaille uniquement \xe0 partir de la cartographie et ne lit jamais le code. C'est une contrainte d\xe9lib\xe9r\xe9e, pas une limitation\xa0: elle oblige chaque correctif \xe0 pointer vers quelque chose que detect a r\xe9ellement d\xe9tect\xe9. Si un p\xe9rim\xe8tre n'a jamais \xe9t\xe9 cartographi\xe9, plan s'arr\xeate et renvoie l'utilisateur vers detect au lieu de deviner."}),"\n",(0,s.jsx)(n.h3,{id:"harden-rem\xe9diation",children:"harden (rem\xe9diation)"}),"\n",(0,s.jsx)(n.p,{children:"Harden est la seule phase qui modifie le code, donc elle avance avec prudence. Savoir si une modification demande l'accord de l'utilisateur rel\xe8ve de l'agent et du mode d'autorisation dans lequel il s'ex\xe9cute, donc harden n'ajoute aucune \xe9tape de confirmation propre. Elle applique un correctif \xe0 la fois, les d\xe9pendances d'abord, puis la priorit\xe9 la plus \xe9lev\xe9e, pour que chaque modification reste petite, relisible et facile \xe0 annuler. Elle n'affaiblit jamais une mesure de protection existante pour faire entrer un nouveau correctif, et elle n'enfreint jamais un principe de s\xe9curit\xe9. Si un correctif entrait en conflit avec un principe, harden s'arr\xeate et fait appara\xeetre le conflit au lieu de l'appliquer. Chaque bloc est consign\xe9 comme Applied, Partial ou Blocked. \"Appliqu\xe9 ne veut pas encore dire v\xe9rifi\xe9\", et c'est la question que traite la phase suivante."}),"\n",(0,s.jsx)(n.h3,{id:"verify-v\xe9rification",children:"verify (v\xe9rification)"}),"\n",(0,s.jsx)(n.p,{children:"Verify v\xe9rifie chaque mesure appliqu\xe9e en lisant le code et en le confrontant \xe0 ce que harden a consign\xe9. La v\xe9rification est cette confrontation du code avec le registre, et elle est statique\xa0: elle confirme qu'une mesure est pr\xe9sente et correcte dans le code, pas qu'elle r\xe9siste \xe0 une attaque sur un syst\xe8me en fonctionnement. Ce contr\xf4le \xe0 l'ex\xe9cution, celui qui lance des attaques r\xe9elles ou simul\xe9es contre le syst\xe8me en production, est hors p\xe9rim\xe8tre par conception. Verify rend l'un de trois verdicts\xa0: risque cl\xf4tur\xe9, risque non cl\xf4tur\xe9, ou impossible \xe0 d\xe9terminer \xe0 partir du code. Il ne produit aucun artefact propre\xa0: harden et verify partagent le registre de durcissement, harden poss\xe9dant ce qui a \xe9t\xe9 fait et verify le verdict et sa raison, et aucun n'\xe9crit jamais dans les champs de l'autre. Une mesure rejet\xe9e est du travail rouvert pour harden, dont l'ex\xe9cution suivante fait primer le verdict sur sa propre lecture du code et r\xe9applique le correctif sur l'\xe9cart exact que nomme la raison. Verify fait confiance au code plut\xf4t qu'au registre, car un registre peut affirmer plus que ce que le code tient. Il est en lecture seule sur le code de l'utilisateur, et il n'adoucit jamais un verdict pour qu'il corresponde au registre. Une mesure peut \xeatre pr\xe9sente et laisser malgr\xe9 tout le risque atteignable par un autre chemin, et dans ce cas le verdict honn\xeate est \"risque non cl\xf4tur\xe9\". Si, en lisant, verify remarque un probl\xe8me de s\xe9curit\xe9 que la cartographie n'a jamais couvert, il n'invente pas de verdict pour lui, puisque la d\xe9tection est le travail de detect\xa0: il signale le probl\xe8me et renvoie l'utilisateur vers detect, pour que le constat entre par le m\xeame flux au lieu de le contourner."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Fil conducteur\xa0: l'envoi de fichiers."})," Un seul constat montre la colonne vert\xe9brale de bout en bout."]}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"detect"})," le trouve\xa0: le syst\xe8me accepte des fichiers des utilisateurs, et le handler d'envoi fait confiance au type MIME envoy\xe9 par le client sans v\xe9rifier le type r\xe9el du fichier. ",(0,s.jsx)(n.em,{children:"Pourquoi c'est important :"})," un fichier d\xe9guis\xe9 en image peut cacher du code malveillant."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"plan"})," d\xe9cide du correctif, priorit\xe9 ",(0,s.jsx)(n.strong,{children:"Critical"}),", en faisant respecter le principe \"Toute entr\xe9e est non fiable tant qu'elle n'a pas \xe9t\xe9 valid\xe9e\"\xa0: v\xe9rifier le type r\xe9el et la taille du fichier, le renommer \xe0 l'enregistrement et stocker les fichiers envoy\xe9s l\xe0 o\xf9 ils ne peuvent pas \xeatre ex\xe9cut\xe9s comme du code."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"harden"})," l'applique, statut ",(0,s.jsx)(n.strong,{children:"Applied"}),"\xa0: le handler d\xe9tecte d\xe9sormais le type r\xe9el \xe0 partir du contenu, impose une taille maximale, rejette tout ce qui est inattendu, renomme \xe0 l'enregistrement et stocke l\xe0 o\xf9 du code ne peut pas s'ex\xe9cuter."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"verify"})," lit le handler, le confronte au registre et rend ",(0,s.jsx)(n.strong,{children:"risque cl\xf4tur\xe9"}),"\xa0: le code fait exactement ce qu'affirme le registre."]}),"\n"]}),"\n",(0,s.jsxs)(n.p,{children:["Le m\xeame nom de constat traverse la cartographie, le plan et le registre de durcissement, et verify agit sur ce registre sous le m\xeame nom\xa0: un verdict ouvert est \xe9crit dans le bloc du constat, et un constat dont la cl\xf4ture est prouv\xe9e est retir\xe9 (",(0,s.jsx)(n.code,{children:"\xa7V"}),"). Ce nom partag\xe9 est son identit\xe9 (",(0,s.jsx)(n.code,{children:"\xa7XI"}),")."]}),"\n"]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"v-cl\xf4turabilit\xe9-un-constat-a-un-\xe9tat-final",children:"V. Cl\xf4turabilit\xe9\xa0: un constat a un \xe9tat final"}),"\n",(0,s.jsxs)(n.p,{children:["La plupart des outils de s\xe9curit\xe9 laissent l'utilisateur avec un backlog qui ne fait que grossir. Le SDH adopte une position diff\xe9rente\xa0: ",(0,s.jsx)(n.strong,{children:"un constat est cl\xf4turable, donc il a un \xe9tat final au lieu de vivre dans un backlog sans fin"})," (figure 2). Cela d\xe9coule directement du principe de mise en coh\xe9rence."]}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"D\xe9finition"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Cl\xf4turabilit\xe9 :"})," un risque dont la cl\xf4ture est v\xe9rifi\xe9e est retir\xe9 de tout le flux, si bien que ce constat atteint un \xe9tat stable et n'est rouvert que lorsque le code change. Un constat a un \xe9tat final, m\xeame si le programme de s\xe9curit\xe9 lui-m\xeame reste continu."]}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Les artefacts du SDH sont des documents vivants, pas des journaux. Chaque fois qu'une phase est relanc\xe9e, elle rev\xe9rifie chaque entr\xe9e existante par rapport \xe0 la r\xe9alit\xe9 actuelle et fait l'une de trois choses\xa0: garder ce qui tient encore, r\xe9\xe9crire ce qui a chang\xe9 ou supprimer ce qui ne s'applique plus. Un constat que le code montre d\xe9sormais r\xe9solu est simplement supprim\xe9. Le registre de travail refl\xe8te le pr\xe9sent, pas le pass\xe9."}),"\n",(0,s.jsx)(n.p,{children:"La cl\xf4ture est cette m\xeame mise en coh\xe9rence arriv\xe9e \xe0 son terme. Quand verify v\xe9rifie qu'un risque est cl\xf4tur\xe9, il retire le constat de tout le flux\xa0: la cartographie, le plan, le registre de durcissement et la carte de suivi. C'est pourquoi verify est la seule phase qui \xe9crit dans les artefacts des autres phases\xa0: c'est la phase qui boucle la boucle. Au moment o\xf9 le constat quitte la cha\xeene, le retrait le condense en une courte entr\xe9e d'un historique qui vit en dehors de la cha\xeene de travail et n'est jamais retrait\xe9. C'est la fronti\xe8re entre dispara\xeetre et \xeatre cl\xf4tur\xe9\xa0: un constat que la mise en coh\xe9rence a supprim\xe9 parce qu'il avait cess\xe9 d'\xeatre vrai ne laisse rien derri\xe8re lui, alors qu'un constat dont la cl\xf4ture est prouv\xe9e gagne sa ligne dans l'historique. Un constat retir\xe9 est ensuite absent de chaque artefact de travail, et cette absence est attendue, ce n'est pas une cha\xeene cass\xe9e."}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-mermaid",children:"stateDiagram-v2\n    direction TB\n    [*] --\x3e OPEN: detect d\xe9tecte\n    OPEN --\x3e Plan: plan\n    Plan --\x3e Harden: harden\n    Harden --\x3e Verify: verify\n    Verify --\x3e StoodDown: risque cl\xf4tur\xe9\n    StoodDown --\x3e SETTLED\n    SETTLED --\x3e OPEN: un changement du code rouvre un constat\n    Plan: plan\n    Harden: harden\n    Verify: verify\n    StoodDown: RETIR\xc9 \xb7 une ligne dans l'historique\n"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Figure 2."})," La machine \xe0 \xe9tats de la cl\xf4turabilit\xe9. Un constat passe de OPEN \xe0 RETIR\xc9 puis \xe0 SETTLED, et ne se rouvre que lorsque le code change."]}),"\n",(0,s.jsx)(n.p,{children:"Quand tout ce qui est dans le p\xe9rim\xe8tre a \xe9t\xe9 retir\xe9, le cycle est au repos, et cet \xe9tat a une forme concr\xe8te\xa0: un artefact dont le dernier constat a \xe9t\xe9 cl\xf4tur\xe9 est supprim\xe9 en entier, donc une cha\xeene enti\xe8rement cl\xf4tur\xe9e ne laisse que les principes de s\xe9curit\xe9 et l'historique, la politique et la preuve. Le cycle n'est rouvert que lorsque le code change. La m\xe9thodologie donne \xe0 chaque constat une fin d\xe9finie, ce qu'un backlog sans fin ne peut justement pas offrir."}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"vi-la-dualit\xe9-prolongateur-des-connaissances-du-d\xe9veloppeur",children:"VI. La dualit\xe9 prolongateur des connaissances du d\xe9veloppeur"}),"\n",(0,s.jsxs)(n.p,{children:["Le SDH ne remplace pas les personnes, et il ne remplace pas les outils Blue Team sp\xe9cialis\xe9s. Il ",(0,s.jsx)(n.strong,{children:"prolonge les connaissances propres du d\xe9veloppeur"}),". Plus un d\xe9veloppeur comprend la s\xe9curit\xe9, plus il peut piloter le flux avec pr\xe9cision, et plus il gagne en autonomie. Un d\xe9veloppeur qui en comprend peu re\xe7oit malgr\xe9 tout un r\xe9sultat s\xfbr, parce que le mode automatique le prot\xe8ge."]}),"\n",(0,s.jsxs)(n.p,{children:["L'inversion de ",(0,s.jsx)(n.code,{children:"\xa7I"}),", selon laquelle les connaissances de s\xe9curit\xe9 r\xe9sident dans la sp\xe9cification, s'applique dans les deux sens. Pour le d\xe9butant, c'est une protection\xa0: il n'a pas besoin de savoir quoi demander, parce que la sp\xe9cification propose. Pour l'expert, c'est une amplification\xa0: la m\xeame sp\xe9cification lui permet d'orienter le flux avec pr\xe9cision au lieu de se battre contre une checklist fig\xe9e."]}),"\n",(0,s.jsx)(n.p,{children:"Chaque phase porte cette dualit\xe9 dans son propre fonctionnement (figure 3). Ex\xe9cut\xe9e sans entr\xe9e, elle agit sur tout le p\xe9rim\xe8tre \xe0 la place de l'utilisateur. Avec une direction, la m\xeame phase se restreint exactement \xe0 ce que l'utilisateur lui a d\xe9sign\xe9."}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-mermaid",children:'flowchart TB\n    inversion["une inversion, deux directions :<br/>les connaissances de s\xe9curit\xe9 r\xe9sident dans la sp\xe9cification"]\n    inversion --\x3e auto["mode automatique (sans entr\xe9e)<br/>la phase propose et agit<br/>sur tout le p\xe9rim\xe8tre"]\n    inversion --\x3e directed["mode dirig\xe9 (avec entr\xe9e)<br/>la phase se restreint exactement<br/>\xe0 ce que l\'utilisateur a d\xe9sign\xe9"]\n    auto --\x3e novice["le d\xe9butant, prot\xe9g\xe9 :<br/>un r\xe9sultat s\xfbr sans<br/>savoir quoi demander"]\n    directed --\x3e expert["l\'expert, amplifi\xe9 :<br/>le flux orient\xe9 avec pr\xe9cision,<br/>pas une checklist fig\xe9e"]\n    novice -.-> phases["les m\xeames cinq phases servent les deux :<br/>charter \xb7 detect \xb7 plan \xb7 harden \xb7 verify"]\n    expert -.-> phases\n'})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Figure 3."})," La dualit\xe9 prolongateur des connaissances du d\xe9veloppeur. Une seule inversion sert deux publics\xa0: le mode automatique prot\xe8ge le d\xe9butant et le mode dirig\xe9 amplifie l'expert, par les m\xeames cinq phases."]}),"\n",(0,s.jsxs)(n.p,{children:["Les sp\xe9cialisations \xe0 la demande (",(0,s.jsx)(n.code,{children:"\xa7VII"}),") rendent cette dualit\xe9 explicite dans leur propre texte. Chacune indique \xe0 l'agent que ses connaissances \"prolongent ton jugement\" et qu'il doit continuer \xe0 raisonner au-del\xe0 de ce qu'apporte la sp\xe9cialisation. Les connaissances sont un plancher, pas un plafond. C'est ce qui sert les deux publics dans l'\xe9quilibre voulu par le document\xa0: la communaut\xe9 des d\xe9veloppeurs gagne un instrument substantiel, et le praticien Blue Team un support structur\xe9 qui ne pr\xe9tend pas faire son travail \xe0 sa place."]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"vii-sp\xe9cialisations-non-invocables-et-prompt-\xe0-la-demande",children:"VII. Sp\xe9cialisations non invocables et prompt \xe0 la demande"}),"\n",(0,s.jsxs)(n.p,{children:["C'est le motif le plus novateur de la m\xe9thodologie. Le SDH porte des connaissances de s\xe9curit\xe9 cibl\xe9es sous forme de sp\xe9cialisations qui se chargent ",(0,s.jsx)(n.strong,{children:"uniquement \xe0 la demande"}),", et c'est l'agent lui-m\xeame qui d\xe9cide lesquelles charger en les confrontant au contexte du projet. Nous appelons cela le ",(0,s.jsx)(n.strong,{children:"prompt \xe0 la demande"}),"\xa0: un moyen pour l'agent de choisir quelles connaissances activer selon le p\xe9rim\xe8tre du projet dans lequel il se trouve, au lieu d'ex\xe9cuter toutes les v\xe9rifications par d\xe9faut. Les sp\xe9cialisations \xe9voluent, et chacune peut changer ou \xeatre remplac\xe9e \xe0 tout moment. La contribution est le motif, pas les sp\xe9cialisations elles-m\xeames."]}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"D\xe9finition"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Prompt \xe0 la demande :"})," l'agent choisit quelles connaissances de s\xe9curit\xe9 activer en les confrontant au p\xe9rim\xe8tre du projet qui se trouve devant lui, si bien que les connaissances pertinentes sont charg\xe9es pour ce qu'est r\xe9ellement le projet, au lieu d'ex\xe9cuter toutes les v\xe9rifications par d\xe9faut."]}),"\n"]}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"D\xe9finition"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Sp\xe9cialisation non invocable :"})," une unit\xe9 de connaissances de s\xe9curit\xe9 cibl\xe9e et ind\xe9pendante du langage pour un contexte donn\xe9, comme l'envoi de fichiers ou le code qui s'ex\xe9cute dans le navigateur. Elle audite et explique, ne r\xe9\xe9crit jamais de code et ne produit jamais d'entr\xe9e d'attaque. Ce n'est pas une commande\xa0: elle se charge quand le contexte qu'elle couvre est dans le p\xe9rim\xe8tre, ou quand un prompt la demande par son nom."]}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Chaque sp\xe9cialisation nomme les formes plus s\xfbres pour les risques qu'elle couvre et indique \xe0 l'agent comment traiter un constat dans chaque phase qui l'utilise\xa0: comment le juger \xe0 la d\xe9tection, comment appliquer son correctif sans risque \xe0 la rem\xe9diation et comment le prouver \xe0 la v\xe9rification."}),"\n",(0,s.jsxs)(n.p,{children:["Son trait distinctif est qu'une sp\xe9cialisation est ",(0,s.jsx)(n.strong,{children:"non invocable \xe0 elle seule"}),"\xa0: ce n'est pas une commande, et au sein du flux, c'est une correspondance qui la charge. La phase de d\xe9tection liste le catalogue une fois, confronte le contexte du projet \xe0 ce que couvre chaque entr\xe9e et ne charge que les sp\xe9cialisations dont le contexte est pr\xe9sent dans le p\xe9rim\xe8tre. Les phases suivantes r\xe9utilisent cette liste au lieu de la refaire, donc une seule correspondance sert toute la cha\xeene, et le mode pr\xe9ventif (",(0,s.jsx)(n.code,{children:"\xa7IX"}),") applique la m\xeame correspondance au travail sur le point d'\xeatre construit. Une sp\xe9cialisation dont le contexte est absent est \xe9cart\xe9e, et l'\xe9cart est aussi justifi\xe9 que le chargement\xa0: chaque entr\xe9e du catalogue re\xe7oit un verdict explicite, appliqu\xe9e ou \xe9cart\xe9e avec la raison lue dans le code, pour qu'un vague sentiment de non-pertinence ne tienne jamais lieu d'absence. N'en trouver aucune applicable est un r\xe9sultat valable."]}),"\n",(0,s.jsxs)(n.p,{children:["Le catalogue est une donn\xe9e, et le faire grandir, c'est un fichier de connaissances plus une ligne de catalogue, jamais une nouvelle commande. Les sp\xe9cialisations int\xe9gr\xe9es sont regroup\xe9es en cat\xe9gories, comme l'OWASP, un langage ou les int\xe9grations d'IA, et le catalogue qu'utilise un projet contient les int\xe9gr\xe9es des cat\xe9gories qu'il a choisies plus ses propres sp\xe9cialisations. Le projet consigne ce choix avec le reste de son \xe9tat, donc toute une \xe9quipe utilise le m\xeame catalogue. C'est le m\xeame principe d'adaptation au contexte que celui des phases, appliqu\xe9 aux connaissances\xa0: les connaissances pertinentes sont charg\xe9es pour ce qu'est r\xe9ellement le projet, au lieu d'ex\xe9cuter toutes les v\xe9rifications par d\xe9faut. La m\xeame propri\xe9t\xe9 permet \xe0 l'utilisateur, et pas seulement au mainteneur, de faire grandir le catalogue\xa0: une source ou un sujet de s\xe9curit\xe9 fourni par l'utilisateur est condens\xe9 en une nouvelle sp\xe9cialisation qui appartient au projet, rejoint son catalogue quelles que soient les cat\xe9gories et se charge exactement comme une int\xe9gr\xe9e, en rempla\xe7ant l'int\xe9gr\xe9e du m\xeame nom. R\xe9diger une sp\xe9cialisation est en soi exclusivement d\xe9fensif et respecte la m\xeame limite que celle que font respecter les sp\xe9cialisations\xa0: la description d'une attaque peut \xeatre la source, mais la sp\xe9cialisation qui en r\xe9sulte audite et explique, elle n'\xe9met jamais d'exploit fonctionnel. Ainsi, l'inversion de ",(0,s.jsx)(n.code,{children:"\xa7I"}),", selon laquelle l'intelligence r\xe9side dans la sp\xe9cification, s'\xe9tend au catalogue lui-m\xeame, que l'utilisateur peut approfondir pour son propre contexte sans \xe9crire de code."]}),"\n",(0,s.jsx)(n.p,{children:"Un court exemple illustre le prompt \xe0 la demande. Detect lit un dossier de code qui s'ex\xe9cute dans le navigateur. Il trouve ce contexte dans le catalogue, charge la sp\xe9cialisation qui le couvre et fait ressortir un constat c\xf4t\xe9 client par les \xe9tapes normales de detect. Les sp\xe9cialisations dont le contexte est absent de ce p\xe9rim\xe8tre ne correspondent pas, donc elles ne se chargent jamais, et chacune est consign\xe9e comme \xe9cart\xe9e. C'est le projet qui a d\xe9termin\xe9 les connaissances pertinentes, pas une configuration fig\xe9e."}),"\n",(0,s.jsxs)(n.p,{children:["Le d\xe9terminisme appara\xeet pr\xe9cis\xe9ment l\xe0 o\xf9 il compte. Une sp\xe9cialisation peut porter un v\xe9rificateur d\xe9terministe, pas seulement du texte\xa0: l\xe0 o\xf9 une classe de risques dispose d'une proc\xe9dure de d\xe9cision nette, un petit programme rend un verdict fixe pour une entr\xe9e donn\xe9e, par exemple un court ensemble de mots comme ",(0,s.jsx)(n.code,{children:"safe"}),", ",(0,s.jsx)(n.code,{children:"unsafe"})," ou ",(0,s.jsx)(n.code,{children:"invalid input"}),". Certaines classes de risques sont d\xe9cidables de fa\xe7on d\xe9terministe exactement de cette mani\xe8re, avec un ensemble de travaux ant\xe9rieurs derri\xe8re la proc\xe9dure de d\xe9cision ",(0,s.jsx)(n.code,{children:"[9]"}),", ",(0,s.jsx)(n.code,{children:"[10]"}),", ",(0,s.jsx)(n.code,{children:"[11]"}),". Le v\xe9rificateur \xe9value soit des candidats fournis par l'agent, soit analyse lui-m\xeame le p\xe9rim\xe8tre pour les trouver, et dans les deux cas c'est le v\xe9rificateur, pas l'agent, qui rend le verdict. Une sp\xe9cialisation suffisamment universelle peut \xeatre marqu\xe9e comme requise dans le catalogue\xa0: elle est alors toujours appliqu\xe9e, et son v\xe9rificateur s'ex\xe9cute sur tout le p\xe9rim\xe8tre. C'est le seul cas o\xf9 des connaissances se chargent sans correspondance de contexte, et il est d\xe9clar\xe9 dans les donn\xe9es du catalogue, jamais d\xe9cid\xe9 par l'agent sur le moment. C'est l\xe0 que le SDH ancre le raisonnement de l'agent dans quelque chose de reproductible, sans pr\xe9tendre que tout le flux est d\xe9terministe."]}),"\n",(0,s.jsxs)(n.p,{children:["Enfin, les sp\xe9cialisations sont ",(0,s.jsx)(n.strong,{children:"d\xe9tachables"}),". Comme les connaissances se suffisent \xe0 elles-m\xeames, un utilisateur peut en ex\xe9cuter une directement dans un prompt qui n'a rien \xe0 voir avec le flux complet du SDH, et garder ainsi la s\xe9curit\xe9 aux c\xf4t\xe9s du d\xe9veloppement ordinaire. Une sp\xe9cialisation dot\xe9e d'un v\xe9rificateur d\xe9terministe peut, par exemple, filtrer chaque candidat produit pendant le d\xe9veloppement ordinaire et ne garder que ceux qui sont s\xfbrs. Ce caract\xe8re d\xe9tachable explique en partie pourquoi le SDH s'adapte \xe0 tant de situations, ce qui est le sujet de ",(0,s.jsx)(n.code,{children:"\xa7VIII"}),", et son expression la plus compl\xe8te est le mode pr\xe9ventif (",(0,s.jsx)(n.code,{children:"\xa7IX"}),"), o\xf9 les m\xeames connaissances prot\xe8gent le d\xe9veloppement ordinaire de bout en bout."]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"viii-ind\xe9pendance-de-l\xe9tat-et-adaptativit\xe9-non-autoritaire",children:"VIII. Ind\xe9pendance de l'\xe9tat et adaptativit\xe9 non autoritaire"}),"\n",(0,s.jsx)(n.p,{children:"Deux propri\xe9t\xe9s distinguent le SDH des m\xe9thodologies de sp\xe9cification rigides."}),"\n",(0,s.jsx)(n.h3,{id:"ind\xe9pendance-de-l\xe9tat",children:"Ind\xe9pendance de l'\xe9tat"}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"D\xe9finition"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Ind\xe9pendance de l'\xe9tat :"})," la m\xe9thodologie ne d\xe9pend pas de l'\xe9tat du d\xe9veloppement. Elle convient \xe0 un r\xe9pertoire vide, \xe0 un projet en cours, \xe0 une seule pull request ou \xe0 une vaste base de code h\xe9rit\xe9e, dans n'importe quelle stack, parce qu'elle d\xe9couvre le point de d\xe9part en le lisant."]}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Chaque phase fonctionne de la m\xeame fa\xe7on, que le projet soit tout neuf ou existe d\xe9j\xe0. La phase charter d\xe9duit des principes de tout le code pr\xe9sent. Detect cartographie tout le code qui s'y trouve, m\xeame s'il y en a tr\xe8s peu. Il n'y a aucun point de d\xe9part suppos\xe9."}),"\n",(0,s.jsx)(n.h3,{id:"adaptativit\xe9-non-autoritaire",children:"Adaptativit\xe9 non autoritaire"}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"D\xe9finition"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Adaptativit\xe9 non autoritaire :"})," la m\xe9thodologie s'adapte au sc\xe9nario au lieu d'imposer un p\xe9rim\xe8tre fixe que l'utilisateur doit suivre. Quand l'utilisateur ne sait pas quoi dire, elle lit l'environnement dans lequel elle a \xe9t\xe9 invoqu\xe9e, g\xe9n\xe8re du contexte et pose les questions qui orientent ce qu'elle fait ensuite."]}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Le mode de proposition de la phase charter en est l'exemple le plus clair\xa0: le SDH d\xe9duit des principes de s\xe9curit\xe9 s\xfbrs par d\xe9faut en analysant le projet, en ne posant de question \xe0 l'utilisateur que lorsqu'un manque change r\xe9ellement le r\xe9sultat, puis les \xe9crit et pr\xe9sente chaque principe en langage courant avec le risque qu'il pr\xe9vient. Les principes de s\xe9curit\xe9 sont un document vivant que l'utilisateur retravaille en relan\xe7ant la phase, pas un contrat soumis \xe0 une demande d'approbation, donc ils n'exigent jamais que l'utilisateur sache quoi demander."}),"\n",(0,s.jsx)(n.p,{children:"Cette adaptativit\xe9 se manifeste par une sensibilit\xe9 \xe0 la forme de l'entr\xe9e\xa0: la m\xeame phase lit ce qu'on lui a donn\xe9 et choisit un mode (figure 4). Un fichier dans le prompt, un constat de la liste, une inqui\xe9tude, une mission cibl\xe9e sur un point faible connu, ou une demande d'analyse exhaustive\xa0: chacun r\xe9pond au besoin de l'utilisateur, parce que le flux est non autoritaire par conception. Rien de tout cela n'affaiblit la base s\xfbre par d\xe9faut. La souplesse fa\xe7onne la mani\xe8re dont la base est appliqu\xe9e, elle ne l'abaisse jamais."}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-mermaid",children:'flowchart TB\n    shape["la phase lit la forme<br/>de ce qu\'on lui a donn\xe9"]\n    shape --\x3e none["aucune entr\xe9e"]\n    shape --\x3e paths["un ou plusieurs chemins"]\n    shape --\x3e concern["une pr\xe9occupation d\xe9crite"]\n    shape --\x3e finding["un constat nomm\xe9"]\n    shape --\x3e band["une tranche de priorit\xe9"]\n    none --\x3e auto["le mode automatique :<br/>proposer, ou analyser<br/>tout le p\xe9rim\xe8tre"]\n    paths --\x3e focus["se concentrer uniquement sur<br/>ces fichiers ou r\xe9pertoires"]\n    concern --\x3e scoped["se limiter \xe0<br/>cette pr\xe9occupation"]\n    finding --\x3e item["agir sur ce seul<br/>\xe9l\xe9ment suivi"]\n    band --\x3e priority["agir uniquement sur Critical,<br/>High, Medium ou Low"]\n'})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Figure 4."})," L'adaptativit\xe9 non autoritaire. La m\xeame phase lit la forme de son entr\xe9e et choisit un mode, donc le p\xe9rim\xe8tre appartient toujours \xe0 l'utilisateur, il n'est jamais impos\xe9."]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"ix-le-mode-pr\xe9ventif-universel-la-m\xeame-d\xe9fense-pendant-la-construction-du-travail",children:"IX. Le mode pr\xe9ventif universel\xa0: la m\xeame d\xe9fense pendant la construction du travail"}),"\n",(0,s.jsx)(n.p,{children:"Le SDH porte un mode compl\xe9mentaire\xa0: le d\xe9veloppement ordinaire, men\xe9 avec la m\xeame d\xe9fense active pendant l'\xe9criture du code. L'utilisateur demande le travail lui-m\xeame, une page de connexion, un envoi de fichiers, un endpoint, et la m\xe9thodologie prot\xe8ge la construction au moment o\xf9 elle se fait, si bien que le r\xe9sultat est s\xfbr par d\xe9faut d\xe8s qu'il arrive, plut\xf4t qu'apr\xe8s une passe de durcissement ult\xe9rieure."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"D\xe9finition"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Le mode pr\xe9ventif :"})," le d\xe9veloppement ordinaire ex\xe9cut\xe9 sous la couche de gouvernance et les connaissances du SDH. Les principes de s\xe9curit\xe9 encadrent la construction, les sp\xe9cialisations pertinentes pour ce qui va \xeatre cr\xe9\xe9 se chargent \xe0 la demande, et le r\xe9sultat est confront\xe9 exactement \xe0 la d\xe9fense utilis\xe9e avant que le travail soit d\xe9clar\xe9 termin\xe9."]}),"\n"]}),"\n",(0,s.jsxs)(n.p,{children:["Ce mode r\xe9utilise chaque \xe9l\xe9ment que les phases portent d\xe9j\xe0, point\xe9 vers du code qui n'existe pas encore. La d\xe9tection du contexte passe du code \xe0 l'intention\xa0: l'agent raisonne sur ce qu'il s'appr\xeate \xe0 construire et sur les fronti\xe8res que traverse ce travail (une connexion implique des identifiants, une session et des entr\xe9es venues de l'ext\xe9rieur), et c'est \xe0 ce raisonnement que le catalogue de connaissances est confront\xe9. Le prompt \xe0 la demande (",(0,s.jsx)(n.code,{children:"\xa7VII"}),") se g\xe9n\xe9ralise ici\xa0: le contexte peut \xeatre d\xe9tect\xe9 dans le plan du code, pas seulement dans du code existant. Les principes de s\xe9curit\xe9 gouvernent comme toujours, et une demande qui enfreindrait un principe est signal\xe9e comme un conflit, jamais construite. La d\xe9fense est appliqu\xe9e au fil de l'\xe9criture, au moment o\xf9 chaque partie est \xe9crite, en validant \xe0 la fronti\xe8re et en choisissant la construction s\xfbre d\xe8s le d\xe9part, si bien qu'une version fonctionnelle mais non s\xfbre n'existe jamais et n'a pas \xe0 \xeatre corrig\xe9e."]}),"\n",(0,s.jsx)(n.p,{children:"Le mode se termine l\xe0 o\xf9 verify commence. Avant que le travail soit d\xe9clar\xe9 termin\xe9, celui qui construit confronte son propre r\xe9sultat \xe0 la d\xe9fense qu'il a utilis\xe9e\xa0: la mesure doit se trouver sur le chemin du risque, pas \xe0 c\xf4t\xe9, elle doit \xeatre compl\xe8te, et l\xe0 o\xf9 une sp\xe9cialisation porte un v\xe9rificateur d\xe9terministe, le verdict du v\xe9rificateur prime sur la propre lecture de l'agent. Un \xe9cart trouv\xe9 \xe0 ce stade est combl\xe9 dans le cadre du m\xeame travail, parce que finir le travail, c'est le finir de fa\xe7on s\xe9curis\xe9e."}),"\n",(0,s.jsxs)(n.p,{children:["Ce que le mode refuse est aussi d\xe9lib\xe9r\xe9 que ce qu'il fait. Il ne construit que ce qui a \xe9t\xe9 demand\xe9 et n'audite rien autour\xa0: auditer l'existant rel\xe8ve des phases. Il n'\xe9crit aucun artefact et ne suit aucun constat, parce qu'un constat est un risque d\xe9tect\xe9 dans l'existant, et que le but de ce mode est que la version non s\xfbre n'arrive jamais. Les deux directions se compl\xe8tent\xa0: les phases cl\xf4turent ce qui est d\xe9j\xe0 l\xe0 (",(0,s.jsx)(n.code,{children:"\xa7V"}),"), et le mode pr\xe9ventif emp\xeache le nouveau travail de le rouvrir. Une cha\xeene au repos reste au repos non parce que le d\xe9veloppement s'est arr\xeat\xe9, mais parce que ce qui est construit pendant ce repos est construit d\xe9fendu."]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"x-security-driven-hardening-face-au-spec-driven-development",children:"X. Security-Driven Hardening face au Spec-Driven Development"}),"\n",(0,s.jsxs)(n.p,{children:["Le Security-Driven Hardening (SDH) est n\xe9 du socle du Spec-Driven Development (SDD) avant de s'en \xe9carter nettement. L'h\xe9ritage structurel est r\xe9el et assum\xe9\xa0: spec-first, pilot\xe9 par agent, un document de gouvernance et un ensemble de commandes par phase qu'ex\xe9cute l'agent. Le SDH r\xe9utilise d\xe9lib\xe9r\xe9ment cette structure. Ce qui diff\xe8re, ce sont le but, le mod\xe8le d'autorit\xe9, l'\xe9tat suppos\xe9 et la condition de fin. Nous traitons le SDD comme une classe, en prenant le rapport de Piskala ",(0,s.jsx)(n.code,{children:"[1]"})," comme formulation canonique de la m\xe9thodologie, Spec Kit de GitHub ",(0,s.jsx)(n.code,{children:"[2]"})," comme bo\xeete \xe0 outils canonique pour agents, et OpenSpec ",(0,s.jsx)(n.code,{children:"[3]"})," comme second outil de la m\xeame famille."]}),"\n",(0,s.jsxs)(n.p,{children:["Le SDD renverse le d\xe9veloppement traditionnel en rendant les sp\xe9cifications ex\xe9cutables\xa0: la sp\xe9cification g\xe9n\xe8re directement une impl\xe9mentation fonctionnelle au lieu de simplement la guider ",(0,s.jsx)(n.code,{children:"[1]"}),". Son ensemble de phases fait avancer une construction ",(0,s.jsx)(n.code,{children:"[2]"})," (\xe9tablir les principes de gouvernance, sp\xe9cifier ce qu'il faut construire, planifier la stack technique, d\xe9couper le plan en t\xe2ches, puis impl\xe9menter). Son document de gouvernance, une constitution de principes, est la pi\xe8ce fondatrice que l'agent doit respecter tout du long. C'est le c\u0153ur de la diff\xe9rence. L'autorit\xe9 du SDD va de la sp\xe9cification vers la construction, et l'impl\xe9mentation est cens\xe9e la suivre."]}),"\n",(0,s.jsx)(n.p,{children:"Le SDH inverse presque chaque axe de ce contrat (tableau 3)."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"Id\xe9e cl\xe9"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"La diff\xe9rence centrale :"})," l'autorit\xe9 du SDD va de la sp\xe9cification vers la construction, et l'impl\xe9mentation est cens\xe9e la suivre. Le SDH est non autoritaire et va dans l'autre sens, vers l'int\xe9rieur \xe0 partir du contexte d\xe9tect\xe9 du syst\xe8me, en durcissant ce qui est d\xe9j\xe0 l\xe0."]}),"\n"]}),"\n",(0,s.jsxs)(n.table,{children:[(0,s.jsx)(n.thead,{children:(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.th,{children:"Axe"}),(0,s.jsx)(n.th,{children:"SDD"}),(0,s.jsx)(n.th,{children:"SDH"})]})}),(0,s.jsxs)(n.tbody,{children:[(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Objectif"}),(0,s.jsx)(n.td,{children:"Livrer des fonctionnalit\xe9s. La sp\xe9cification devient une impl\xe9mentation fonctionnelle."}),(0,s.jsx)(n.td,{children:"Durcir ce qui existe ou est en cours de construction. Chaque phase est orient\xe9e vers la d\xe9fense."})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Mod\xe8le d'autorit\xe9"}),(0,s.jsx)(n.td,{children:"Autoritaire. La sp\xe9cification et la constitution enferment la construction dans un p\xe9rim\xe8tre qu'elle doit suivre."}),(0,s.jsx)(n.td,{children:"Non autoritaire. Le SDH s'adapte au sc\xe9nario, et l'utilisateur peut reformuler, supprimer ou r\xe9duire la port\xe9e."})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"\xc9tat suppos\xe9"}),(0,s.jsx)(n.td,{children:"Une construction qui avance \xe0 partir d'une sp\xe9cification."}),(0,s.jsx)(n.td,{children:"Ind\xe9pendant de l'\xe9tat\xa0: r\xe9pertoire vide, projet en cours, une seule PR ou code h\xe9rit\xe9."})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Condition de fin"}),(0,s.jsx)(n.td,{children:"Se termine quand la fonctionnalit\xe9 est construite."}),(0,s.jsx)(n.td,{children:"Cl\xf4turable. Un constat atteint un \xe9tat stable et n'est rouvert que lorsque le code change."})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Document de gouvernance"}),(0,s.jsx)(n.td,{children:"Une constitution de principes que l'agent doit respecter."}),(0,s.jsxs)(n.td,{children:["Des principes de s\xe9curit\xe9 formul\xe9s en termes de risques (chacun porte une ligne ",(0,s.jsx)(n.code,{children:"Why:"}),"), explicitement pas un contrat fig\xe9."]})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Comment les connaissances grandissent"}),(0,s.jsx)(n.td,{children:"Ajouter une commande (ou \xe9tendre l'ensemble des phases)."}),(0,s.jsx)(n.td,{children:"Ajouter une sp\xe9cialisation non invocable que l'agent charge \xe0 la demande\xa0: un fichier plus une ligne de catalogue, sans nouvelle commande."})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Qui il sert"}),(0,s.jsx)(n.td,{children:"Quelqu'un qui construit et fait avancer une fonctionnalit\xe9."}),(0,s.jsx)(n.td,{children:"Tout utilisateur, d\xe9veloppeur ou non, servi par le m\xeame flux."})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Ce qui modifie le code"}),(0,s.jsx)(n.td,{children:"La phase d'impl\xe9mentation g\xe9n\xe8re la construction."}),(0,s.jsx)(n.td,{children:"Seule la phase harden modifie le code, un correctif \xe0 la fois."})]})]})]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Tableau 3."})," Le SDD face au SDH sur huit axes. Une structure emprunt\xe9e, un contrat invers\xe9."]}),"\n",(0,s.jsxs)(n.p,{children:["Pour \xeatre juste envers cette filiation\xa0: le SDD est une ant\xe9riorit\xe9 \xe9prouv\xe9e, et le SDH lui doit la structure sur laquelle il repose. L'\xe9cart n'est pas une critique du SDD, qui r\xe9sout bien un autre probl\xe8me (faire avancer une construction). Le SDH reprend la m\xeame m\xe9canique \xe9prouv\xe9e et l'oriente vers la d\xe9fense, l'adaptativit\xe9 et la cl\xf4ture. OpenSpec ",(0,s.jsx)(n.code,{children:"[3]"}),", organis\xe9 autour de propositions de changement, de listes de t\xe2ches et de sp\xe9cifications par changement, confirme le motif\xa0: la famille fait avancer une construction \xe0 partir d'une sp\xe9cification, l\xe0 o\xf9 le SDH durcit un syst\xe8me vers l'int\xe9rieur \xe0 partir de son contexte d\xe9tect\xe9. M\xeame le mode pr\xe9ventif du SDH (",(0,s.jsx)(n.code,{children:"\xa7IX"}),"), le seul endroit o\xf9 il accompagne une construction qui avance, conserve le contrat invers\xe9\xa0: il gouverne la mani\xe8re dont le travail est construit et ne d\xe9cide jamais de ce qu'il faut construire."]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"xi-rigueur-ding\xe9nierie-la-discipline-du-suivi",children:"XI. Rigueur d'ing\xe9nierie\xa0: la discipline du suivi"}),"\n",(0,s.jsxs)(n.p,{children:['La discipline "mettre en coh\xe9rence, jamais seulement ajouter" (',(0,s.jsx)(n.code,{children:"\xa7V"}),") a besoin d'un socle qui survive aux refactorisations. Un constat doit rester un seul \xe9l\xe9ment dans chaque phase qui le touche, et un fichier renomm\xe9 ou d\xe9plac\xe9 ne doit pas casser la cha\xeene. Le SDH r\xe9sout ce probl\xe8me avec l'",(0,s.jsx)(n.strong,{children:"identit\xe9 par le nom"})," et des ",(0,s.jsx)(n.strong,{children:"chemins conserv\xe9s uniquement dans le suivi"}),"."]}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"D\xe9finition"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Identit\xe9 par le nom :"})," l'identit\xe9 d'un constat est son nom, \xe9crit \xe0 l'identique dans chaque artefact. Le texte porte le nom, jamais un chemin. Les chemins de fichiers ne se trouvent que dans la carte de suivi, donc un renommage ou un fichier d\xe9plac\xe9 ne casse le lien qu'\xe0 un seul endroit."]}),"\n"]}),"\n",(0,s.jsxs)(n.p,{children:["Chaque constat de detect est un \xe9l\xe9ment suivi. Son identit\xe9 est son ",(0,s.jsx)(n.strong,{children:"nom"}),", le titre de section, \xe9crit \xe0 l'identique dans la cartographie, le plan et le registre de durcissement. Les phases suivantes r\xe9utilisent ce nom tel quel lorsqu'elles agissent sur le m\xeame \xe9l\xe9ment, et verify \xe9crit son verdict dans le registre de durcissement sous ce m\xeame nom. La carte de suivi ne contient que du suivi, une entr\xe9e par \xe9l\xe9ment\xa0:"]}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-json",children:'{ "name": "File uploads", "paths": ["src/routes/upload.ts"] }\n'})}),"\n",(0,s.jsx)(n.p,{children:"La carte n'enregistre ni texte, ni annotation, ni identifiant distinct, ni phase. Les artefacts r\xe9dig\xe9s portent la formulation, et la carte ne porte que l'identit\xe9 et les chemins. Les chemins de fichiers sont la seule donn\xe9e volatile, et ils ne se trouvent qu'ici. Un renommage ou un fichier d\xe9plac\xe9 ne peut casser le lien qu'\xe0 un seul endroit, jamais dans deux copies divergentes."}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-mermaid",children:'flowchart TB\n    detect["la cartographie"] --\x3e name\n    plan["le plan de d\xe9fense"] --\x3e name\n    harden["le registre de durcissement<br/>verify y \xe9crit son verdict"] --\x3e name\n    name["nom = &quot;File uploads&quot;<br/>le texte porte le nom, jamais un chemin"]\n    name -.-> tracking\n    tracking["la carte de suivi<br/>{ name: &quot;File uploads&quot;,<br/>paths: [&quot;src/routes/upload.ts&quot;] }<br/>le chemin ne se trouve qu\'ici, donc un renommage ne corrige que cette entr\xe9e"]\n'})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Figure 5."})," Le convoyeur d'identit\xe9. Un m\xeame nom de constat traverse chaque artefact, tandis que son chemin ne se trouve que dans la carte de suivi, donc un renommage se corrige \xe0 un seul endroit."]}),"\n",(0,s.jsxs)(n.p,{children:["Deux actes entretiennent la carte dans le flux normal, et un troisi\xe8me se tient \xe0 part, comme maintenance. ",(0,s.jsx)(n.strong,{children:"Track"})," est un enregistrement additif\xa0: une phase signale les constats qu'elle a \xe9crits, et le moteur enregistre les nouveaux et suit un chemin renomm\xe9 pour les autres, en classant chacun comme nouveau, d\xe9plac\xe9 ou inchang\xe9. Il ne supprime jamais rien que la phase n'ait pas signal\xe9. ",(0,s.jsx)(n.strong,{children:"Untrack"})," retire les constats que verify a cl\xf4tur\xe9s\xa0: en une seule passe d\xe9terministe, il condense chacun en son entr\xe9e d'historique, supprime toute sa section des artefacts, efface un artefact dont le dernier constat a disparu et supprime son entr\xe9e de suivi, si bien que l'agent ne fait rien de tout cela \xe0 la main. L\xe0 o\xf9 la passe d\xe9terministe ne peut pas aller sans risque, un nom retir\xe9 encore cit\xe9 dans le texte d'un autre constat, il signale l'endroit \xe0 l'agent au lieu de deviner une modification. Ce sont ces deux actes que les phases appellent pendant leur ex\xe9cution. ",(0,s.jsx)(n.strong,{children:"Repair"})," est l'acte de maintenance\xa0: une phase lui d\xe9l\xe8gue automatiquement le travail quand sa propre mise en coh\xe9rence trouve le suivi incoh\xe9rent (un chemin enregistr\xe9 qui n'existe plus), et sinon il s'ex\xe9cute \xe0 la demande. Il r\xe9aligne toute la carte d'un coup, en lisant chaque artefact et le code actuel, en corrigeant les chemins de chaque \xe9l\xe9ment et en faisant ressortir ce qu'il ne peut pas trancher seul\xa0: un orphelin (un \xe9l\xe9ment suivi qu'aucun artefact ne nomme plus) ou un candidat au renommage (un \xe9l\xe9ment dont les chemins correspondent \xe0 un autre nom signal\xe9)."]}),"\n",(0,s.jsx)(n.p,{children:"Repair est de la maintenance, pas une sixi\xe8me phase. Il ne touche ni au code de l'utilisateur ni aux artefacts r\xe9dig\xe9s, seulement au suivi. Il lit le code source de l'utilisateur pour une seule raison, conna\xeetre le nouveau chemin d'un fichier renomm\xe9, et il ne r\xe9dige jamais de contenu de s\xe9curit\xe9. L'humain est l'arbitre final sur la seule question que le moteur refuse de deviner\xa0: un \xe9l\xe9ment disparu a-t-il \xe9t\xe9 r\xe9solu ou simplement renomm\xe9\xa0? Mieux vaut demander que deviner, car un \xe9l\xe9ment supprim\xe9 \xe0 tort casse la cha\xeene."}),"\n",(0,s.jsx)(n.p,{children:"La m\xe9thodologie s'applique \xe0 elle-m\xeame sa propre discipline de d\xe9fense. Les moteurs d\xe9terministes sont invoqu\xe9s comme des programmes en ligne de commande, et chaque entr\xe9e est pass\xe9e comme un argument de processus distinct, ce qui la rend inerte\xa0: une valeur contenant des guillemets ou des backticks ne peut jamais s'injecter dans la commande. Une v\xe9rification inconnue \xe9choue au lieu de r\xe9pondre, donc une v\xe9rification mal orthographi\xe9e ne passe jamais pour un r\xe9sultat propre. Le SDH n'exempte pas sa propre plomberie du principe de s\xfbret\xe9 par d\xe9faut."}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"xii-le-support-une-architecture-ind\xe9pendante-de-lagent-comme-preuve-de-portabilit\xe9",children:"XII. Le support\xa0: une architecture ind\xe9pendante de l'agent comme preuve de portabilit\xe9"}),"\n",(0,s.jsx)(n.p,{children:"Pour que le SDH soit une convention que d'autres adoptent, il ne doit \xeatre li\xe9 ni \xe0 un agent ni \xe0 une stack, donc son support s\xe9pare trois responsabilit\xe9s (figure 6). Lagune prouve que c'est r\xe9alisable."}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"La valeur de s\xe9curit\xe9"})," est \xe9crite une seule fois et ne sait rien de l'agent qui l'ex\xe9cute\xa0: les instructions des phases et les mod\xe8les qu'elles remplissent, le catalogue de connaissances et les moteurs d\xe9terministes. ",(0,s.jsx)(n.strong,{children:"La distribution"})," est mince\xa0: sa seule mission est d'apporter cette valeur \xe0 un agent donn\xe9, sous la forme et \xe0 l'endroit qu'il attend, et elle ne porte aucune logique de s\xe9curit\xe9 propre. ",(0,s.jsx)(n.strong,{children:"L'\xe9tat du projet"})," appartient au projet\xa0: les principes de s\xe9curit\xe9, les artefacts des phases, la carte de suivi, les cat\xe9gories qu'il a choisies et ses propres sp\xe9cialisations, commit\xe9s et relisibles comme n'importe quelle autre partie de son code."]}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-mermaid",children:'flowchart TB\n    value["la valeur de s\xe9curit\xe9, \xe9crite une seule fois<br/>instructions des phases \xb7 mod\xe8les \xb7 catalogue de connaissances \xb7 moteurs d\xe9terministes<br/>ne sait rien de l\'agent qui l\'ex\xe9cute"]\n    delivery["la distribution<br/>apporte cette valeur \xe0 chaque agent sous la forme qu\'il attend<br/>ne porte aucune logique de s\xe9curit\xe9"]\n    agent["l\'agent<br/>ex\xe9cute les phases"]\n    project["l\'\xe9tat du projet<br/>commit\xe9 avec son code<br/>principes de s\xe9curit\xe9 \xb7 artefacts des phases \xb7 suivi \xb7 cat\xe9gories \xb7 sp\xe9cialisations propres"]\n    value --\x3e delivery --\x3e agent\n    agent --\x3e|"lit et \xe9crit"| project\n'})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Figure 6."})," Le support ind\xe9pendant de l'agent. La valeur de s\xe9curit\xe9 est \xe9crite une seule fois, une distribution mince l'apporte \xe0 chaque agent, et l'\xe9tat reste celui du projet."]}),"\n",(0,s.jsx)(n.p,{children:"Comme la distribution ne porte aucune logique de s\xe9curit\xe9, la fa\xe7on dont elle est construite ne change rien au SDH. Un support peut construire lui-m\xeame la distribution ou la confier \xe0 un \xe9cosyst\xe8me qui distribue d\xe9j\xe0 des skills d'agent, comme le fait l'impl\xe9mentation de r\xe9f\xe9rence, et les phases, leurs artefacts et leurs garanties restent les m\xeames. Rien de tout cela n'est propre \xe0 un langage ou \xe0 un runtime non plus. L'impl\xe9mentation de r\xe9f\xe9rence se trouve \xe9crite dans une stack donn\xe9e, mais la m\xe9thodologie est la fronti\xe8re entre ces responsabilit\xe9s, pas la cha\xeene d'outils qui les construit. La m\xeame conception pourrait \xeatre r\xe9impl\xe9ment\xe9e dans un tout autre langage sans changer ce qu'est le SDH."}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"xiii-cas-pratique-le-sdh-de-bout-en-bout",children:"XIII. Cas pratique\xa0: le SDH de bout en bout"}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"Cas pratique"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Durcissement d\xe9fensif d'une surface d'envoi de fichiers et d'administration."}),"\n",(0,s.jsx)(n.strong,{children:"Contexte :"})," une petite application qui accepte des fichiers envoy\xe9s par les utilisateurs et les liste sur une page d'administration.\n",(0,s.jsx)(n.strong,{children:"Sch\xe9ma :"})," charter \u2192 detect (avec des connaissances \xe0 la demande activ\xe9es par le contexte) \u2192 plan \u2192 harden \u2192 verify, avec une cl\xf4ture et un v\xe9ritable \xe9chec.\n",(0,s.jsx)(n.strong,{children:"R\xe9sultat (capacit\xe9) :"})," un risque dont la cl\xf4ture est v\xe9rifi\xe9e, retir\xe9 de toute la cha\xeene, et une mesure v\xe9rifi\xe9e comme ",(0,s.jsx)(n.em,{children:"non"})," cl\xf4tur\xe9e, renvoy\xe9e vers harden. Le verdict refl\xe8te le code, pas le registre."]}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Ceci est un exemple illustratif du fonctionnement de la m\xe9thodologie, pas une \xe9tude mesur\xe9e sur le terrain, et il ne rapporte aucune m\xe9trique d'efficacit\xe9."})}),"\n",(0,s.jsxs)(n.p,{children:["Un parcours continu montre la m\xe9thodologie en action, et pas seulement ses parties. Nous prolongeons le fil de l'envoi de fichiers de ",(0,s.jsx)(n.code,{children:"\xa7IV"})," avec une activation de connaissances \xe0 la demande et une cl\xf4ture, et nous incluons un v\xe9ritable \xe9chec."]}),"\n",(0,s.jsxs)(n.ol,{children:["\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"charter"})," propose le principe \"Toute entr\xe9e est non fiable tant qu'elle n'a pas \xe9t\xe9 valid\xe9e\", avec son risque en langage courant\xa0: une entr\xe9e non v\xe9rifi\xe9e est le moyen le plus courant de casser un syst\xe8me."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"detect"})," analyse la route d'envoi et la petite page d'administration qui liste les fichiers envoy\xe9s. Il d\xe9tecte le constat sur l'envoi (le handler fait confiance au type MIME du client). La page d'administration s'ex\xe9cute dans le navigateur, un contexte que reconna\xeet le prompt \xe0 la demande (",(0,s.jsx)(n.code,{children:"\xa7VII"}),"), donc detect charge la sp\xe9cialisation de ce contexte et fait ressortir un second constat\xa0: un endroit o\xf9 un nom de fichier est \xe9crit dans la page sous forme de balisage plut\xf4t que de texte, si bien qu'un nom forg\xe9 peut s'ex\xe9cuter comme script dans le navigateur du visiteur. Les sp\xe9cialisations dont le contexte est absent de ce p\xe9rim\xe8tre ne se chargent jamais, et chaque \xe9cart est consign\xe9 avec l'absence lue dans le code."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"plan"})," attribue au correctif de l'envoi la priorit\xe9 Critical, rattach\xe9e au principe\xa0: v\xe9rifier le type r\xe9el et la taille du fichier, renommer \xe0 l'enregistrement, stocker l\xe0 o\xf9 du code ne peut pas s'ex\xe9cuter. Il attribue au second correctif la priorit\xe9 High\xa0: afficher le nom de fichier comme du texte, pas comme du balisage."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"harden"})," applique d'abord le correctif de l'envoi (priorit\xe9 la plus \xe9lev\xe9e) et le consigne Applied, puis le second, Applied."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"verify"})," lit chaque endroit et confronte le code au registre. La mesure sur l'envoi est efficace\xa0: le handler d\xe9tecte le type r\xe9el \xe0 partir du contenu, impose une taille maximale et refuse le reste. Verdict\xa0: risque cl\xf4tur\xe9. Verify retire le constat de l'envoi de toute la cha\xeene, et son r\xe9sum\xe9 condens\xe9 rejoint l'historique."]}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Le v\xe9ritable \xe9chec suit. Supposons que le second correctif de harden ait ajout\xe9 un utilitaire s\xfbr d'affichage en texte, mais laiss\xe9 l'ancien appel qui \xe9crit du balisage encore atteignable par un autre chemin de code. Verify lit la page, voit l'utilitaire s\xfbr, et voit aussi que le chemin non s\xfbr est toujours actif. La mesure est pr\xe9sente, mais le risque n'est pas cl\xf4tur\xe9. Verify refuse d'adoucir le verdict pour qu'il corresponde au registre. Il rend \"risque non cl\xf4tur\xe9\", consigne l'\xe9cart et renvoie vers harden. Une mesure qui ne traite pas enti\xe8rement le risque n'est pas une validation."}),"\n",(0,s.jsx)(n.p,{children:"C'est le caract\xe8re de la m\xe9thodologie en un seul exemple\xa0: une d\xe9tection adapt\xe9e au contexte, des correctifs prioris\xe9s et rattach\xe9s \xe0 des principes, une application prudente, et une v\xe9rification qui rapporte l'\xe9tat r\xe9el du code, quel que soit le registre."}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"xiv-quand-utiliser-le-sdh-et-ses-limites",children:"XIV. Quand utiliser le SDH, et ses limites"}),"\n",(0,s.jsxs)(n.p,{children:["Le SDH est rarement disproportionn\xe9 comme peut l'\xeatre un processus lourd, parce qu'il est ind\xe9pendant de l'\xe9tat et cl\xf4turable\xa0: il se r\xe9duit \xe0 un seul fichier et \xe0 une seule pr\xe9occupation, et il atteint un \xe9tat stable au lieu de laisser une charge permanente. Sa limite n'est pas la taille du projet, c'est la ",(0,s.jsx)(n.strong,{children:"profondeur d'assurance"}),"."]}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-mermaid",children:'flowchart TB\n    q1{"Le code fait-il quoi que ce soit qui touche \xe0 la s\xe9curit\xe9 ?<br/>(entr\xe9es, authentification, donn\xe9es, secrets, appels externes)"}\n    q1 --\x3e|non| little["Le SDH apporte peu ici."]\n    q1 --\x3e|oui| q2{"Ex\xe9cutez le SDH. Y a-t-il une exigence de conformit\xe9,<br/>ou une fonction de s\xe9curit\xe9 d\xe9di\xe9e ?"}\n    q2 --\x3e|non| baseline["Le SDH est une base d\xe9fendable."]\n    q2 --\x3e|oui| carrier["Le SDH est le support structur\xe9 :<br/>il appuie la revue et l\'audit des experts,<br/>il ne les remplace pas."]\n'})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Figure 7."})," Quand utiliser le SDH. Le crit\xe8re est d'abord la pertinence pour la s\xe9curit\xe9, puis la profondeur d'assurance, jamais la taille du projet."]}),"\n",(0,s.jsx)(n.p,{children:"L\xe0 o\xf9 le SDH atteint sa limite\xa0: les comportements qui n'apparaissent qu'\xe0 l'ex\xe9cution du syst\xe8me (verify lit le code, il n'ex\xe9cute pas le syst\xe8me), les risques qui d\xe9pendent d'une configuration ou d'un environnement que l'agent ne peut pas lire, et les contextes \xe0 fort enjeu o\xf9 une revue d'expert est requise quoi qu'il arrive. Dans chacun de ces cas, le SDH apporte encore de la valeur comme premier passage structur\xe9, mais c'est un plancher, pas un plafond."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"Id\xe9e cl\xe9"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"La limite :"})," la limite du SDH est la profondeur d'assurance, pas la taille du projet. Il peut servir de base d\xe9fendable presque partout, et il appuie la revue d'experts l\xe0 o\xf9 les enjeux l'exigent, mais il ne remplace ni les tests d'un syst\xe8me en fonctionnement ni le jugement d'un professionnel de la s\xe9curit\xe9."]}),"\n"]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"xv-discussion-positionnement-limites-et-ce-que-le-sdh-ne-pr\xe9tend-pas",children:"XV. Discussion\xa0: positionnement, limites et ce que le SDH ne pr\xe9tend pas"}),"\n",(0,s.jsx)(n.p,{children:"Le SDH est pr\xe9cis sur ses limites."}),"\n",(0,s.jsx)(n.h3,{id:"il-prolonge-il-ne-remplace-pas",children:"Il prolonge, il ne remplace pas"}),"\n",(0,s.jsxs)(n.p,{children:["Le SDH ne remplace ni les professionnels de la s\xe9curit\xe9 ni les outils Blue Team sp\xe9cialis\xe9s. Il prolonge les connaissances du d\xe9veloppeur (",(0,s.jsx)(n.code,{children:"\xa7VI"}),"). Une affirmation mesur\xe9e est la bonne\xa0: bien appliqu\xe9, le SDH ",(0,s.jsx)(n.strong,{children:"peut"})," cl\xf4turer efficacement de vrais risques, en particulier pour des projets qui n'auraient sinon aucun passage de s\xe9curit\xe9. Ce n'est pas une garantie, et ce n'est pas un substitut \xe0 une revue d'expert l\xe0 o\xf9 les enjeux l'exigent."]}),"\n",(0,s.jsx)(n.h3,{id:"exclusivement-d\xe9fensif-par-construction",children:"Exclusivement d\xe9fensif, par construction"}),"\n",(0,s.jsx)(n.p,{children:"Le SDH audite, durcit et v\xe9rifie. Il ne produit jamais d'outils offensifs, d'exploits ni de contournement de la d\xe9tection \xe0 des fins nuisibles. Le contenu de s\xe9curit\xe9 \xe0 double usage n'est acceptable que dans un cadre clairement d\xe9fensif et autoris\xe9. C'est une limite stricte, pas une pr\xe9f\xe9rence."}),"\n",(0,s.jsx)(n.h3,{id:"une-v\xe9rification-de-fond-pas-de-fa\xe7ade",children:"Une v\xe9rification de fond, pas de fa\xe7ade"}),"\n",(0,s.jsx)(n.p,{children:"Verify v\xe9rifie en lisant le code et en le confrontant au registre, pas en ex\xe9cutant le syst\xe8me. C'est une v\xe9rification statique\xa0: elle confirme qu'une mesure est pr\xe9sente et correcte dans le code, et elle ne prouve pas que la mesure r\xe9siste \xe0 une attaque \xe0 l'ex\xe9cution. Ainsi, \"impossible \xe0 d\xe9terminer \xe0 partir du code\" est un verdict l\xe9gitime, pas un \xe9chec dissimul\xe9 derri\xe8re une validation. Quand l'\xe9l\xe9ment de preuve n'est pas dans le code (il d\xe9pend de la configuration, ou d'un chemin que l'agent ne peut pas lire), le SDH le dit au lieu de deviner."}),"\n",(0,s.jsx)(n.h3,{id:"un-d\xe9terminisme-circonscrit-et-nomm\xe9",children:"Un d\xe9terminisme circonscrit, et nomm\xe9"}),"\n",(0,s.jsxs)(n.p,{children:["L'essentiel du SDH repose sur le raisonnement de l'agent, ce qui permet son adaptation au contexte. Le d\xe9terminisme est r\xe9serv\xe9 aux moteurs d\xe9terministes\xa0: les v\xe9rificateurs qu'une sp\xe9cialisation peut porter (",(0,s.jsx)(n.code,{children:"\xa7VII"}),") et le moteur de suivi (",(0,s.jsx)(n.code,{children:"\xa7XI"}),"). Le document ne brouille pas cette fronti\xe8re. L\xe0 o\xf9 un r\xe9sultat est d\xe9terministe, c'est le r\xe9sultat d'un programme. L\xe0 o\xf9 il est raisonn\xe9, c'est la lecture du code par l'agent, avec l'utilisateur comme arbitre final."]}),"\n",(0,s.jsx)(n.h3,{id:"co\xfbt-et-\xe9chelle",children:"Co\xfbt et \xe9chelle"}),"\n",(0,s.jsxs)(n.p,{children:["Une analyse compl\xe8te consomme beaucoup de tokens. Les modes manuels (",(0,s.jsx)(n.code,{children:"\xa7VI"}),", ",(0,s.jsx)(n.code,{children:"\xa7VIII"}),") existent en partie pour garder le co\xfbt proportionnel \xe0 la pr\xe9occupation."]}),"\n",(0,s.jsx)(n.h3,{id:"lutilisateur-est-larbitre-final",children:"L'utilisateur est l'arbitre final"}),"\n",(0,s.jsx)(n.p,{children:"Le SDH demande \xe0 l'humain de trancher entre renomm\xe9 et r\xe9solu, et l'approbation de ses modifications du code reste l\xe0 o\xf9 l'utilisateur gouverne d\xe9j\xe0 son agent, dans le mode d'autorisation o\xf9 il l'ex\xe9cute. La m\xe9thodologie propose et v\xe9rifie. Elle ne passe pas outre la personne."}),"\n",(0,s.jsx)(n.h3,{id:"objections-et-r\xe9ponses",children:"Objections et r\xe9ponses"}),"\n",(0,s.jsx)(n.p,{children:"Un sceptique de bonne foi soul\xe8vera plusieurs objections. Les plus substantielles m\xe9ritent d'\xeatre pos\xe9es dans leurs propres termes."}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:'"N\'est-ce pas juste un analyseur statique avec un LLM greff\xe9 dessus\xa0?"'})," Non. Un analyseur statique ex\xe9cute toutes ses r\xe8gles par d\xe9faut. Le SDH d\xe9tecte d'abord ce qu'est le syst\xe8me, puis va chercher les connaissances pertinentes (",(0,s.jsx)(n.code,{children:"\xa7II"}),", ",(0,s.jsx)(n.code,{children:"\xa7VII"}),"), et il n'",(0,s.jsx)(n.em,{children:"int\xe8gre"})," un v\xe9rificateur d\xe9terministe que l\xe0 o\xf9 une classe de risques dispose d'une proc\xe9dure de d\xe9cision nette. Le raisonnement part du contexte, le d\xe9terminisme est cibl\xe9."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:'"N\'est-ce pas juste une checklist de s\xe9curit\xe9\xa0?"'})," Non. Le SDH inverse la checklist\xa0: la d\xe9tection vient d'abord, et les connaissances sont charg\xe9es pour ce que fait r\xe9ellement le projet (",(0,s.jsx)(n.code,{children:"\xa7II"}),", ",(0,s.jsx)(n.code,{children:"\xa7VII"}),")."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:'"N\'est-ce pas juste du SDD rebaptis\xe9 pour la s\xe9curit\xe9\xa0?"'})," Non. Le SDH emprunte la structure du SDD et inverse son contrat\xa0: l'autorit\xe9, l'\xe9tat suppos\xe9, la condition de fin et le public servi diff\xe8rent tous (",(0,s.jsx)(n.code,{children:"\xa7X"}),"). M\xeame m\xe9canique, direction oppos\xe9e."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:'"Une m\xe9thode raisonn\xe9e par IA n\'invente-t-elle pas simplement des constats\xa0?"'})," La conception contraint l'invention au lieu de compter sur le bon comportement du mod\xe8le. Detect ne consigne que ce que le code \xe9taye (\"la d\xe9tection, pas l'invention\", ",(0,s.jsx)(n.code,{children:"\xa7IV"}),'), verify confronte le code au registre et peut r\xe9pondre "impossible \xe0 d\xe9terminer \xe0 partir du code" (',(0,s.jsx)(n.code,{children:"\xa7XV"}),"), des v\xe9rificateurs d\xe9terministes ancrent les cas d\xe9cidables (",(0,s.jsx)(n.code,{children:"\xa7VII"}),"), et l'utilisateur est l'arbitre final. Cela ne rend pas l'agent infaillible, cela rend ses affirmations v\xe9rifiables."]}),"\n",(0,s.jsx)(n.p,{children:'Une remarque sur le positionnement. Le SDH est d\xe9fini ici ind\xe9pendamment de son impl\xe9mentation de r\xe9f\xe9rence. Les cinq phases, les principes de s\xe9curit\xe9 formul\xe9s en termes de risques, la r\xe8gle "mettre en coh\xe9rence, jamais seulement ajouter" et sa cl\xf4turabilit\xe9, les connaissances charg\xe9es par prompt \xe0 la demande, le mode pr\xe9ventif, le suivi par identit\xe9 de nom et la limite exclusivement d\xe9fensive constituent la m\xe9thodologie. Une autre \xe9quipe pourrait les impl\xe9menter dans une autre stack et un autre \xe9cosyst\xe8me d\'agents, et le r\xe9sultat serait toujours du SDH. Lagune en est la preuve, pas la d\xe9finition.'}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"xvi-les-\xe9cueils-et-comment-le-sdh-les-\xe9vite-structurellement",children:"XVI. Les \xe9cueils, et comment le SDH les \xe9vite structurellement"}),"\n",(0,s.jsx)(n.p,{children:"Les m\xe9thodologies de cette famille partagent un ensemble connu de modes de d\xe9faillance. La r\xe9ponse du SDH \xe0 la plupart d'entre eux est structurelle, int\xe9gr\xe9e au flux plut\xf4t que laiss\xe9e \xe0 la discipline."}),"\n",(0,s.jsxs)(n.table,{children:[(0,s.jsx)(n.thead,{children:(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.th,{children:"\xc9cueil"}),(0,s.jsx)(n.th,{children:"La d\xe9faillance"}),(0,s.jsx)(n.th,{children:"La r\xe9ponse structurelle du SDH"})]})}),(0,s.jsxs)(n.tbody,{children:[(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Sp\xe9cification qui pourrit, backlog p\xe9rim\xe9"}),(0,s.jsx)(n.td,{children:"Les artefacts accumulent des entr\xe9es mortes auxquelles plus personne ne se fie"}),(0,s.jsxs)(n.td,{children:["Mettre en coh\xe9rence, jamais seulement ajouter (",(0,s.jsx)(n.code,{children:"\xa7V"}),")\xa0: chaque ex\xe9cution rev\xe9rifie chaque entr\xe9e et supprime ce qui est r\xe9solu"]})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Fausse confiance, validation trompeuse"}),(0,s.jsx)(n.td,{children:"On suppose qu'une mesure pr\xe9sente cl\xf4ture le risque"}),(0,s.jsxs)(n.td,{children:['Verify confronte le code au registre, donc "risque non cl\xf4tur\xe9" et "impossible \xe0 d\xe9terminer" sont des verdicts \xe0 part enti\xe8re (',(0,s.jsx)(n.code,{children:"\xa7IV"}),", ",(0,s.jsx)(n.code,{children:"\xa7XV"}),")"]})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Avalanche de checklists"}),(0,s.jsx)(n.td,{children:"Des \xe9l\xe9ments g\xe9n\xe9riques masquent le seul risque qui compte"}),(0,s.jsxs)(n.td,{children:["Le contexte plut\xf4t que le g\xe9n\xe9rique, avec un prompt \xe0 la demande qui ne charge que ce que le p\xe9rim\xe8tre exige (",(0,s.jsx)(n.code,{children:"\xa7VII"}),")"]})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"D\xe9pendance \xe0 un outil"}),(0,s.jsx)(n.td,{children:"La m\xe9thode est soud\xe9e \xe0 un seul \xe9diteur ou agent"}),(0,s.jsxs)(n.td,{children:["Un support ind\xe9pendant de l'agent\xa0: la valeur de s\xe9curit\xe9 est \xe9crite une seule fois, et sa distribution \xe0 chaque agent ne porte aucune logique de s\xe9curit\xe9 (",(0,s.jsx)(n.code,{children:"\xa7XII"}),")"]})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"La boucle sans fin"}),(0,s.jsx)(n.td,{children:"Le backlog ne se ferme jamais, le travail n'est jamais au repos"}),(0,s.jsxs)(n.td,{children:["La cl\xf4turabilit\xe9 et l'\xe9tat de repos (",(0,s.jsx)(n.code,{children:"\xa7V"}),")"]})]})]})]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Tableau 4."})," Les \xe9cueils connus de cette famille de m\xe9thodologies et la r\xe9ponse structurelle du SDH \xe0 chacun."]}),"\n",(0,s.jsx)(n.p,{children:"Nommer l'\xe9cueil et d\xe9signer le m\xe9canisme, c'est tout l'int\xe9r\xeat\xa0: ce ne sont pas des avertissements \xe0 la prudence, ce sont des propri\xe9t\xe9s du flux."}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"xvii-travaux-futurs",children:"XVII. Travaux futurs"}),"\n",(0,s.jsx)(n.p,{children:"La m\xe9thodologie et son impl\xe9mentation de r\xe9f\xe9rence ont des prochaines \xe9tapes claires."}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Faire grandir le catalogue de connaissances :"}),"\nChaque ajout garde la forme de ",(0,s.jsx)(n.code,{children:"\xa7VII"})," : un fichier de connaissances et une ligne de catalogue, sans nouvelle commande. La voie c\xf4t\xe9 utilisateur existe d\xe9j\xe0\xa0: l'utilisateur condense ses propres sp\xe9cialisations \xe0 la demande. Davantage de langages, de runtimes et de classes de risques int\xe9gr\xe9s, chacun rejoignant une cat\xe9gorie, constituent la direction c\xf4t\xe9 mainteneur, et les sp\xe9cialisations sont appel\xe9es \xe0 \xe9voluer."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Davantage de v\xe9rificateurs d\xe9terministes :"}),"\nL\xe0 o\xf9 une classe de risques dispose d'une proc\xe9dure de d\xe9cision nette, une sp\xe9cialisation peut porter un v\xe9rificateur d\xe9terministe qui ancre le raisonnement de l'agent dans un verdict reproductible. L'\xe9tendre \xe0 davantage de classes de risques est une direction naturelle."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"\xc9valuation empirique :"}),"\nLa question ouverte la plus importante est l'efficacit\xe9 mesur\xe9e\xa0: la qualit\xe9 des cl\xf4tures et les taux de faux verdicts sur de vraies bases de code. Une \xe9tude des r\xe9sultats de s\xe9curit\xe9 du SDH rel\xe8ve des travaux futurs, et les affirmations de ce document sont circonscrites en cons\xe9quence."]}),"\n"]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"xviii-conclusion",children:"XVIII. Conclusion"}),"\n",(0,s.jsx)(n.p,{children:"Le d\xe9veloppement assist\xe9 par IA a ouvert une br\xe8che de s\xe9curit\xe9 que les checklists g\xe9n\xe9riques ne peuvent pas combler, parce que le risque qui compte est propre \xe0 ce que fait r\xe9ellement un syst\xe8me, et que la personne qui le livre ne sait peut-\xeatre pas quoi demander. Le SDH comble cette br\xe8che avec un flux adapt\xe9 au contexte, exclusivement d\xe9fensif et cl\xf4turable, dans lequel les connaissances de s\xe9curit\xe9 r\xe9sident dans la m\xe9thodologie et ses sp\xe9cialisations \xe0 la demande, une base sur laquelle chaque utilisateur peut construire. Il d\xe9tecte le contexte r\xe9el du syst\xe8me, trie les risques que porte ce contexte, applique les correctifs avec prudence et v\xe9rifie chacun, puis retire ce qu'il a cl\xf4tur\xe9 pour que chaque constat atteigne un \xe9tat final. La m\xeame d\xe9fense s'ex\xe9cute aussi de fa\xe7on pr\xe9ventive pendant la construction du nouveau travail, pour que ce que le flux cl\xf4ture reste cl\xf4tur\xe9. Il s'adapte \xe0 n'importe quel \xe9tat de d\xe9veloppement dans n'importe quelle stack, et il prolonge les connaissances du d\xe9veloppeur au lieu de remplacer les personnes et les outils qui font d\xe9j\xe0 ce travail."}),"\n",(0,s.jsx)(n.p,{children:"Lagune en est la preuve, mais la contribution est la convention. Le SDH est propos\xe9 comme le flux de s\xe9curit\xe9 essentiel de l'\xe8re du d\xe9veloppement avec l'IA, pour que d'autres l'adoptent, l'affinent et l'impl\xe9mentent dans leurs propres stacks."}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"r\xe9f\xe9rences",children:"R\xe9f\xe9rences"}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"[1]"}),' D. B. Piskala, "Spec-Driven Development: From Code to Contract in the Age of AI Coding Assistants," arXiv preprint arXiv:2602.00180v1 [cs.SE], Jan. 2026. (Submitted to AIWare 2026.) [Online]. Available: ',(0,s.jsx)(n.a,{href:"https://arxiv.org/abs/2602.00180",children:"https://arxiv.org/abs/2602.00180"})]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"[2]"}),' GitHub, "Spec Kit: Toolkit for Spec-Driven Development." [Online]. Available: ',(0,s.jsx)(n.a,{href:"https://github.com/github/spec-kit",children:"https://github.com/github/spec-kit"}),". Accessed: 2026."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"[3]"}),' Fission AI, "OpenSpec: Spec-Driven Development for AI Coding Assistants." [Online]. Available: ',(0,s.jsx)(n.a,{href:"https://github.com/Fission-AI/OpenSpec",children:"https://github.com/Fission-AI/OpenSpec"}),". Accessed: 2026."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"[4]"}),' B. Chess and G. McGraw, "Static Analysis for Security," IEEE Security & Privacy, vol. 2, no. 6, pp. 76-79, 2004, doi: 10.1109/MSP.2004.111.']}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"[5]"}),' OWASP Foundation, "Source Code Analysis Tools." [Online]. Available: ',(0,s.jsx)(n.a,{href:"https://owasp.org/www-community/Source_Code_Analysis_Tools",children:"https://owasp.org/www-community/Source_Code_Analysis_Tools"}),". Accessed: 2026."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"[6]"}),' OWASP Foundation, "OWASP Top 10:2021." [Online]. Available: ',(0,s.jsx)(n.a,{href:"https://owasp.org/Top10/",children:"https://owasp.org/Top10/"}),". Accessed: 2026."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"[7]"}),' MITRE, "Common Weakness Enumeration (CWE)." [Online]. Available: ',(0,s.jsx)(n.a,{href:"https://cwe.mitre.org/",children:"https://cwe.mitre.org/"}),". Accessed: 2026."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"[8]"}),' N. Perry, M. Srivastava, D. Kumar, and D. Boneh, "Do Users Write More Insecure Code with AI Assistants?," in Proc. ACM SIGSAC Conf. on Computer and Communications Security (CCS \'23), 2023, pp. 2785-2799, doi: 10.1145/3576915.3623157. [Online]. Available: ',(0,s.jsx)(n.a,{href:"https://arxiv.org/abs/2211.03622",children:"https://arxiv.org/abs/2211.03622"})]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"[9]"}),' J. Davis and contributors, "safe-regex: Detect Possibly Catastrophic, Exponential-Time Regular Expressions." [Online]. Available: ',(0,s.jsx)(n.a,{href:"https://github.com/davisjam/safe-regex",children:"https://github.com/davisjam/safe-regex"}),". Accessed: 2026."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"[10]"}),' D. Soshnikov, "regexp-tree: Regular Expressions Processor in JavaScript." [Online]. Available: ',(0,s.jsx)(n.a,{href:"https://github.com/DmitrySoshnikov/regexp-tree",children:"https://github.com/DmitrySoshnikov/regexp-tree"}),". Accessed: 2026."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"[11]"}),' T. Jenkinson, "redos-detector: A CLI and Library to Score How Vulnerable a Regex Pattern Is to ReDoS Attacks." [Online]. Available: ',(0,s.jsx)(n.a,{href:"https://github.com/tjenkinson/redos-detector",children:"https://github.com/tjenkinson/redos-detector"}),". Accessed: 2026."]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"annexe-a-les-principes-mot-pour-mot",children:"Annexe A\xa0: les principes, mot pour mot"}),"\n",(0,s.jsxs)(n.ol,{children:["\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"S\xfbr par d\xe9faut, en langage courant, pour tous \xe0 \xe9galit\xe9 :"}),"\nChaque valeur par d\xe9faut, chaque message et chaque correctif doit \xeatre s\xfbr d'embl\xe9e et compr\xe9hensible par tout utilisateur, d\xe9veloppeur ou non. Aucun profil d'utilisateur n'est privil\xe9gi\xe9 par rapport \xe0 un autre."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Le contexte plut\xf4t que le g\xe9n\xe9rique :"}),"\nChaque phase doit partir du contexte d\xe9tect\xe9 par detect et agir sur ce que fait r\xe9ellement le syst\xe8me. Pr\xe9f\xe9rez les recommandations propres \xe0 ce contexte aux checklists g\xe9n\xe9riques. Les connaissances de s\xe9curit\xe9 r\xe9sident dans la sp\xe9cification et ses sp\xe9cialisations \xe0 la demande, et prolongent tout ce qu'apporte l'utilisateur."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"La souplesse plut\xf4t que la rigidit\xe9 :"}),"\nLe SDH s'adapte au projet et \xe0 l'utilisateur. Les principes, exigences et recommandations sont des points de d\xe9part, pas un contrat fig\xe9. Laissez l'utilisateur reformuler, supprimer, ajouter ou r\xe9duire la port\xe9e de n'importe quoi. La souplesse n'affaiblit jamais la base s\xfbre par d\xe9faut, elle permet seulement \xe0 l'utilisateur de fa\xe7onner la mani\xe8re dont elle s'applique."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Mettre en coh\xe9rence, jamais seulement ajouter :"}),"\nLes artefacts sont des documents vivants, pas des journaux. Quand une phase est relanc\xe9e, mettez chaque entr\xe9e existante en coh\xe9rence avec la r\xe9alit\xe9 actuelle\xa0: gardez ce qui tient encore, r\xe9\xe9crivez ce qui a chang\xe9 et supprimez ce qui ne s'applique plus. La cl\xf4ture est cette m\xeame mise en coh\xe9rence arriv\xe9e \xe0 son terme."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Exclusivement d\xe9fensif :"}),"\nLe SDH audite, durcit et v\xe9rifie. Il ne produit jamais d'outils offensifs, d'exploits \xe0 usage malveillant ni de contournement de la d\xe9tection \xe0 des fins nuisibles. Le contenu de s\xe9curit\xe9 \xe0 double usage n'est acceptable que dans un cadre clairement d\xe9fensif et autoris\xe9."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Spec-first, pilot\xe9 par agent, orient\xe9 vers la s\xe9curit\xe9 :"}),"\nConstruisez le workflow \xe0 partir d'une structure \xe9prouv\xe9e\xa0: des mod\xe8les, des commandes, des principes de s\xe9curit\xe9 qui gouvernent et un agent qui ex\xe9cute les phases. R\xe9impl\xe9mentez cette structure dans un but d\xe9fensif."]}),"\n"]})]})}function o(e={}){let{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}}}]);